// assets/opencode/src/runtime.js
// Shared runtime helpers: error text, console warnings, and the `phasegent`
// CLI probes (Bun shell).
//
// OpenCode v2 has no structured warning field on the plugin context, so every
// degradation is reported on the host console and never throws into a tool
// call.

function errorText(error) {
  return String(error && error.message ? error.message : error);
}

function warn(message) {
  try {
    console.warn(message);
  } catch (_) {
    // ignore: a broken console must not break path redirection
  }
}

// Bounded placement diagnostics on the existing console channel (issue 919 P1).
// OpenCode v2 has no structured logger on the plugin context, so diagnostics
// reuse `warn` rather than guessing an unsupported surface. Only the fixed
// allowlist of fields below is ever emitted — never prompts, secrets, titles, or
// raw provider/config payloads — and the event vocabulary is stable so an
// operator can grep one line per placement decision.
const PLACEMENT_DIAGNOSTIC_FIELDS = ["session", "parent", "from", "to", "reason", "outcome"];

function placementDiagnostic(event, fields) {
  const parts = [];
  for (const key of PLACEMENT_DIAGNOSTIC_FIELDS) {
    const value = fields && fields[key];
    if (typeof value === "string" && value.length > 0) parts.push(`${key}=${value}`);
  }
  const label = typeof event === "string" && event.length > 0 ? event : "unknown";
  warn(`phasegent: placement ${label}${parts.length > 0 ? ` ${parts.join(" ")}` : ""}`);
}

async function safeText(command) {
  try {
    const text = (await command.text()).trim();
    return { ok: true, value: text };
  } catch (error) {
    return { ok: false, error: errorText(error) };
  }
}

function phasegentCallsDisabled() {
  try {
    return Boolean(process && process.env && process.env.PHASEGENT_WORKTREE_NO_DISCOVER === "1");
  } catch (_) {
    return false;
  }
}

// The host platform decides how a role is expressed in a shell command: POSIX
// shells take the `NAME=value` prefix, PowerShell needs `$env:NAME='value'`.
function isWindowsHost() {
  try {
    return typeof process !== "undefined" && process.platform === "win32";
  } catch (_) {
    return false;
  }
}

// `args` is spread into separate argv entries by Bun's shell interpolation, and
// `env` (when given) is layered over the inherited environment for this probe
// only, so a role never leaks into the host process.
function phasegentCommand(args, cwd, env) {
  const command = Bun.$`phasegent ${args}`;
  const scoped = cwd ? command.cwd(cwd) : command;
  return (env ? scoped.env({ ...process.env, ...env }) : scoped).quiet();
}

function locationDirectory(context) {
  const location = context && context.location;
  return location && typeof location.directory === "string" ? location.directory : null;
}

// assets/opencode/src/binding.js
// Local, offline probes around the `phasegent` CLI: branch binding, worktree
// acquire, active lease status, and the full lease history. All calls stay
// local: no network, no credentials, no .env copies.
//
// The role a probe needs is scoped to that single call through the
// `PHASEGENT_ROLE` environment entry, so the host process environment is never
// mutated (issue #588 phase 2).


// `worktree acquire` is orchestrator-only; the lease reads are executor-scoped.
const ORCHESTRATOR_ENV = { PHASEGENT_ROLE: "orchestrator" };
const EXECUTOR_ENV = { PHASEGENT_ROLE: "executor" };
const LEASE_PAGE_LIMIT = 100;
const MAX_LEASE_PAGES = 10_000;
const PAGING_FIELDS = ["items", "page", "limit", "total_count", "has_more"];
const LEASE_STATUSES = new Set(["active", "retained", "released"]);

async function readBranchBinding(cwd) {
  const result = await safeText(phasegentCommand(["issue", "status"], cwd));
  if (!result.ok || !result.value) return null;
  try {
    const parsed = JSON.parse(result.value);
    if (parsed && typeof parsed.issue_id === "number" && parsed.issue_id > 0) {
      return parsed.issue_id;
    }
  } catch (_) {
  }
  return null;
}

async function acquireWorktree(issueId, sessionId, cwd, options) {
  // Lease-owned operations need an explicit identity (issue 651 P4):
  // the CLI removed its fabricated fallback owner, so an anonymous
  // acquire would hard-error. Refuse upfront with an actionable warning
  // instead of spending a CLI round-trip on a guaranteed failure; the
  // caller falls back to its ownerless path.
  if (!sessionId) {
    warn(
      `phasegent: cannot acquire a worktree for issue ${issueId} without a session identity; ` +
        "the lease must be owned, so pass the host session id or run " +
        `\`phasegent worktree acquire --issue ${issueId} --isolate\` by hand`,
    );
    return null;
  }
  const args = [
    "worktree", "acquire",
    "--issue", String(issueId),
    "--format", "json",
  ];
  // The host strategy's explicit create request passes `isolate`, which
  // forces a fresh directory; a caller that only wants the reuse decision
  // leaves it unset.
  if (options && options.isolate) args.push("--isolate");
  args.push("--session", String(sessionId));
  const result = await safeText(phasegentCommand(args, cwd, ORCHESTRATOR_ENV));
  if (!result.ok || !result.value) return null;
  try {
    const parsed = JSON.parse(result.value);
    if (parsed && typeof parsed.path === "string" && parsed.path.length > 0) {
      return parsed;
    }
  } catch (_) {
  }
  return null;
}

function isObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function validLease(lease) {
  return (
    isObject(lease) &&
    typeof lease.lease_id === "string" && lease.lease_id.length > 0 &&
    typeof lease.repo_identity === "string" && lease.repo_identity.length > 0 &&
    Number.isSafeInteger(lease.issue) && lease.issue > 0 &&
    typeof lease.session === "string" && lease.session.length > 0 &&
    typeof lease.checkout_path === "string" && lease.checkout_path.length > 0 &&
    typeof lease.worktree_path === "string" && lease.worktree_path.length > 0 &&
    typeof lease.branch === "string" &&
    LEASE_STATUSES.has(lease.status) &&
    Number.isSafeInteger(lease.created_at) &&
    Number.isSafeInteger(lease.heartbeat_at) &&
    (!Object.hasOwn(lease, "release_reason") || typeof lease.release_reason === "string")
  );
}

function validUniqueLeases(leases) {
  if (!Array.isArray(leases)) return false;
  const ids = new Set();
  for (const lease of leases) {
    if (!validLease(lease) || ids.has(lease.lease_id)) return false;
    ids.add(lease.lease_id);
  }
  return true;
}

function isLegacyLeaseResult(parsed) {
  return !PAGING_FIELDS.some((field) => Object.hasOwn(parsed, field));
}

async function readCompleteLeaseCollection(argsForPage, cwd, contextField, expectedIssue, executePage) {
  const runPage = executePage || ((args) => safeText(phasegentCommand(args, cwd, EXECUTOR_ENV)));
  const leases = [];
  const leaseIds = new Set();
  let expectedContext;
  let totalCount;
  let pageCount;

  for (let page = 1; page <= MAX_LEASE_PAGES; page += 1) {
    const args = [...argsForPage(page), "--page", String(page), "--limit", String(LEASE_PAGE_LIMIT)];
    const result = await runPage(args);
    if (!result.ok || !result.value) return null;

    let parsed;
    try {
      parsed = JSON.parse(result.value);
    } catch (_) {
      return null;
    }
    if (!isObject(parsed)) return null;

    if (page === 1 && isLegacyLeaseResult(parsed)) {
      if (
        !Array.isArray(parsed.leases) ||
        !validUniqueLeases(parsed.leases) ||
        (contextField === "issue" && parsed.issue !== expectedIssue) ||
        (contextField === "repo_identity" &&
          (typeof parsed.repo_identity !== "string" || parsed.repo_identity.length === 0))
      ) {
        return null;
      }
      return parsed.leases;
    }

    if (
      parsed.page !== page ||
      parsed.limit !== LEASE_PAGE_LIMIT ||
      !Array.isArray(parsed.items) ||
      parsed.items.length > LEASE_PAGE_LIMIT ||
      typeof parsed.has_more !== "boolean" ||
      !Number.isSafeInteger(parsed.total_count) ||
      parsed.total_count < 0 ||
      parsed.total_count > LEASE_PAGE_LIMIT * MAX_LEASE_PAGES
    ) {
      return null;
    }

    const context = parsed[contextField];
    if (contextField === "issue") {
      if (!Number.isSafeInteger(context) || context !== expectedIssue) return null;
    } else if (typeof context !== "string" || context.length === 0) {
      return null;
    }
    if (page === 1) {
      expectedContext = context;
      totalCount = parsed.total_count;
      pageCount = Math.max(1, Math.ceil(totalCount / LEASE_PAGE_LIMIT));
      if (pageCount > MAX_LEASE_PAGES) return null;
    } else if (context !== expectedContext || parsed.total_count !== totalCount) {
      return null;
    }

    if (page > pageCount) return null;
    const expectedItems = Math.min(LEASE_PAGE_LIMIT, totalCount - leases.length);
    if (parsed.items.length !== expectedItems) return null;
    const expectedMore = leases.length + parsed.items.length < totalCount;
    if (parsed.has_more !== expectedMore) return null;

    for (const lease of parsed.items) {
      if (!validLease(lease) || leaseIds.has(lease.lease_id)) return null;
      leaseIds.add(lease.lease_id);
      leases.push(lease);
    }

    if (!parsed.has_more) {
      return leases.length === totalCount && page === pageCount ? leases : null;
    }
  }

  return null;
}

async function readIssueLeases(issueId, cwd, executePage) {
  const issue = Number(issueId);
  if (!Number.isSafeInteger(issue) || issue <= 0) return null;
  const leases = await readCompleteLeaseCollection(
    (page) => ["worktree", "status", "--issue", String(issue)],
    cwd,
    "issue",
    issue,
    executePage,
  );
  return leases;
}

// `worktree status` selects active rows only, so a converged issue looks empty
// there: its closed marker is read through `worktree list --no-sync`, whose
// envelope keeps every row (active and terminal) of the resolved repo
// identity. `--no-sync` keeps the probe local and offline: no provider
// resolution, no reconciliation pass.
async function readIssueLeaseHistory(issueId, cwd, executePage) {
  const issue = Number(issueId);
  if (!Number.isSafeInteger(issue) || issue <= 0) return null;
  const leases = await readCompleteLeaseCollection(
    () => ["worktree", "list", "--no-sync"],
    cwd,
    "repo_identity",
    undefined,
    executePage,
  );
  return leases === null ? null : leases.filter((lease) => lease.issue === issue);
}

// `issue close` and `issue sync` converge an issue's lease rows instead of
// deleting them: the rows keep their status (`retained` / `released`) and carry
// a release reason of "issue closed" ("issue closed: <session>") or "issue
// closed on the remote (issue sync)" (src/lifecycle.rs, src/cli/sync.rs). That
// reason is the adapter's local, offline marker for a closed issue, so the lazy
// path can refuse a fresh worktree without a provider call. The rows come from
// the lease history (`worktree list --no-sync`), which keeps terminal rows.
const ISSUE_CLOSED_REASON = /^issue closed/i;

function issueClosedLocally(leases) {
  if (!Array.isArray(leases)) return false;
  return leases.some(
    (lease) =>
      Boolean(lease) &&
      typeof lease === "object" &&
      typeof lease.release_reason === "string" &&
      ISSUE_CLOSED_REASON.test(lease.release_reason.trim()),
  );
}

function pickActiveWorktreePath(leases) {
  if (!Array.isArray(leases)) return null;
  let best = null;
  for (const lease of leases) {
    if (!lease || typeof lease !== "object") continue;
    if (lease.status !== "active") continue;
    if (typeof lease.worktree_path !== "string" || lease.worktree_path.length === 0) {
      continue;
    }
    if (!best) {
      best = lease;
      continue;
    }
    const heartbeat = lease.heartbeat_at ?? "";
    const bestHeartbeat = best.heartbeat_at ?? "";
    if (String(heartbeat) > String(bestHeartbeat)) {
      best = lease;
    }
  }
  return best ? best.worktree_path : null;
}

// assets/opencode/src/roles.js
// Agent-role mapping for session events (issue #541; issue #859 P1 exact match).
//
// `event.agent` is the agent id the host reports for the current tool call, and
// the role decides command rewriting: the per-invocation `PHASEGENT_ROLE` scope,
// a sub-agent's refusal of the orchestrator-only `issue create`/`bind`, and the
// downgrade of a claimed elevated role. `explore` maps to its own least-privilege
// role (issue #754 P3): the CLI grants it issue read plus structured `record`
// read, and an authorized recon `record create` only — never the reviewer
// surface, and never ordinary comment/status/admin/lease writes.
//
// Canonical IDs are exact after lowercasing: orchestrator, executor, reviewer,
// explore only (issue #859 P1). Compound or substring lookalikes
// (`task-executor`, `my-orchestrator`, `reviewer-2`) are unknown and get no
// role, so an unknown custom agent never elevates to a privileged role. An
// unknown agent still receives the managed session marker through the shell
// bridge and fails closed as managed-without-role instead of Operator.

const AGENT_ROLE_HINTS = [
  ["orchestrator", "orchestrator"],
  ["executor", "executor"],
  ["reviewer", "reviewer"],
  ["explore", "explore"],
];

function agentRole(event) {
  const agent = event && typeof event.agent === "string" ? event.agent.toLowerCase() : "";
  if (!agent) return null;
  for (const [hint, role] of AGENT_ROLE_HINTS) {
    if (agent === hint) return role;
  }
  return null;
}

function isSubagentSession(event) {
  const role = agentRole(event);
  return role !== null && role !== "orchestrator";
}

// The agent id the host reports for the current call, lowercased.
function agentName(event) {
  return event && typeof event.agent === "string" ? event.agent.toLowerCase() : "";
}

// assets/opencode/src/broker.js
// Loopback identity broker (issue #22 P1).
//
// The plugin owns the host facts of a managed shell: the agent id the host
// reported for the current tool call and the session id it runs in. The
// broker keeps those facts per live tool call and answers the CLI's
// verification request locally.
//
// Protocol: versioned newline-delimited JSON over one TCP connection per
// CLI invocation.
//
//   -> {"v":1,"op":"identify","token":"<opaque>","session":"<session id>"}
//   <- {"v":1,"ok":true,"role":"executor","session":"<session id>"}
//   <- {"v":1,"ok":false,"error":"unknown token"}
//
// The request never carries a role: the broker derives the role from the
// facts it stored, so a caller can never select an identity. The token is a
// strong random opaque value held in plugin memory; it is bound to one tool
// call, it may serve several CLI invocations inside that call, and it is
// revoked when the call completes or its entry expires.
//
// The listener binds the loopback interface only, so no verification
// request can leave the machine. Nothing about a token, a session id, or a
// role is ever logged.

import net from "node:net";
import { randomBytes } from "node:crypto";

const BROKER_ADDR_ENV = "PHASEGENT_BROKER_ADDR";
const BROKER_TOKEN_ENV = "PHASEGENT_BROKER_TOKEN";
const BROKER_PROTOCOL_VERSION = 1;
const BROKER_DEFAULT_TTL_MS = 5 * 60 * 1000;
const BROKER_MAX_REQUEST_BYTES = 4096;
const BROKER_MAX_ENTRIES = 128;
const BROKER_MAX_CONNECTIONS = 64;
const BROKER_REQUEST_DEADLINE_MS = 2000;

const TOKEN_PATTERN = /^[A-Za-z0-9]{32,128}$/;

function defaultNow() {
  return Date.now();
}

// A credential is 32 cryptographic random bytes rendered as hex. Where the
// runtime exposes no cryptographic source the generator fails closed: the
// broker never falls back to Math.random or any other weak entropy.
function defaultRandomToken() {
  try {
    return randomBytes(32).toString("hex");
  } catch (_) {
    return null;
  }
}

function optionNumber(options, name, fallback, minimum) {
  const value = options && options[name];
  return typeof value === "number" && Number.isFinite(value) && value >= minimum
    ? Math.floor(value)
    : fallback;
}

function isNonEmptyString(value) {
  return typeof value === "string" && value.length > 0;
}

// Immediate teardown for rejected, timed-out, and stopped connections. A
// reset (when the runtime exposes it) makes the peer observe closure promptly;
// plain destroy is the fallback. Never used to answer a valid request.
function destroySocket(socket) {
  try {
    if (typeof socket.resetAndDestroy === "function") {
      socket.resetAndDestroy();
      return;
    }
  } catch (_) {}
  try {
    socket.destroy();
  } catch (_) {}
}

// A host tool-call id is the only handle that can revoke this credential when
// the call completes. A missing, null, or blank id cannot be revoked, so it
// must never receive a token.
function isUsableLifecycleId(value) {
  return typeof value === "string" && value.trim().length > 0;
}

// Per-plugin-instance broker. Options are injectable for deterministic
// tests: `{ now, randomToken, ttlMs, maxEntries, maxConnections,
// requestDeadlineMs }`. Each setup call owns an isolated token map and its
// own loopback listener; no module-global state is shared across plugin
// instances.
function createIdentityBroker(options) {
  const now =
    options && typeof options.now === "function" ? options.now : defaultNow;
  const randomToken =
    options && typeof options.randomToken === "function"
      ? options.randomToken
      : defaultRandomToken;
  const ttlMs =
    options && typeof options.ttlMs === "number" && options.ttlMs >= 0
      ? options.ttlMs
      : BROKER_DEFAULT_TTL_MS;
  const maxEntries = optionNumber(options, "maxEntries", BROKER_MAX_ENTRIES, 1);
  const maxConnections = optionNumber(
    options,
    "maxConnections",
    BROKER_MAX_CONNECTIONS,
    1,
  );
  const requestDeadlineMs = optionNumber(
    options,
    "requestDeadlineMs",
    BROKER_REQUEST_DEADLINE_MS,
    1,
  );

  // token -> { token, role, sessionID, toolCallId, timestamp }
  const entries = new Map();
  // socket -> { responded, buffer, deadline }
  const connections = new Map();
  let server = null;
  let address = null;

  function pruneExpired(current) {
    for (const [token, entry] of entries) {
      if (current - entry.timestamp > ttlMs) {
        entries.delete(token);
      }
    }
  }

  // Store one tool call and return its opaque token. A token is never
  // reused: a generated value that is already live is discarded and a new
  // one is drawn. Expired entries are pruned first, but a full live map
  // refuses the new credential instead of evicting another live call.
  function mint(role, sessionID, toolCallId) {
    if (!isNonEmptyString(sessionID)) return null;
    // No usable lifecycle handle means no later revocation: fail closed and
    // let the shell stay managed-without-role.
    if (!isUsableLifecycleId(toolCallId)) return null;
    const current = now();
    pruneExpired(current);
    if (entries.size >= maxEntries) return null;
    for (let attempt = 0; attempt < 8; attempt += 1) {
      const candidate = randomToken();
      if (typeof candidate !== "string" || !TOKEN_PATTERN.test(candidate)) {
        continue;
      }
      if (entries.has(candidate)) continue;
      entries.set(candidate, {
        token: candidate,
        // The role is the host fact the plugin observed. An unknown agent
        // has no role at all, and the broker then refuses the request
        // instead of guessing one.
        role: isNonEmptyString(role) ? role : null,
        sessionID,
        toolCallId,
        timestamp: current,
      });
      return candidate;
    }
    return null;
  }

  // Revoke every credential of one tool call: the call is over, so no
  // later invocation may reuse its identity.
  function revokeToolCall(toolCallId) {
    if (!isNonEmptyString(toolCallId)) return 0;
    let removed = 0;
    for (const [token, entry] of entries) {
      if (entry.toolCallId === toolCallId) {
        entries.delete(token);
        removed += 1;
      }
    }
    return removed;
  }

  // Answer one verification request. The request carries a token and a
  // session id; the reply echoes the session id of the stored fact, so a
  // reply for another session can never be mistaken for this one.
  function handle(line) {
    let request = null;
    try {
      request = JSON.parse(line);
    } catch (_) {
      return JSON.stringify({ v: BROKER_PROTOCOL_VERSION, ok: false, error: "malformed request" });
    }
    if (!request || typeof request !== "object") {
      return JSON.stringify({ v: BROKER_PROTOCOL_VERSION, ok: false, error: "malformed request" });
    }
    if (request.v !== BROKER_PROTOCOL_VERSION) {
      return JSON.stringify({
        v: BROKER_PROTOCOL_VERSION,
        ok: false,
        error: "unsupported protocol version",
      });
    }
    if (request.op !== "identify") {
      return JSON.stringify({ v: BROKER_PROTOCOL_VERSION, ok: false, error: "unsupported operation" });
    }
    if (!isNonEmptyString(request.token) || !isNonEmptyString(request.session)) {
      return JSON.stringify({ v: BROKER_PROTOCOL_VERSION, ok: false, error: "malformed request" });
    }
    const current = now();
    pruneExpired(current);
    const entry = entries.get(request.token);
    if (!entry) {
      return JSON.stringify({ v: BROKER_PROTOCOL_VERSION, ok: false, error: "unknown token" });
    }
    if (entry.sessionID !== request.session) {
      return JSON.stringify({ v: BROKER_PROTOCOL_VERSION, ok: false, error: "session mismatch" });
    }
    if (!entry.role) {
      return JSON.stringify({ v: BROKER_PROTOCOL_VERSION, ok: false, error: "unknown agent" });
    }
    return JSON.stringify({
      v: BROKER_PROTOCOL_VERSION,
      ok: true,
      role: entry.role,
      session: entry.sessionID,
    });
  }

  // Serve one connection: bound the concurrent sockets, read one request
  // line, answer at most once, and close. The absolute deadline starts at
  // accept and is never extended by incoming bytes, so a slow or trickling
  // client cannot hold a socket open past it.
  function serve(socket) {
    socket.on("error", () => {});
    if (connections.size >= maxConnections) {
      // Refuse transport outright: no overload reply, no tracked deadline,
      // and no untracked delayed callback. Immediate teardown releases the
      // descriptor, so a half-open rejected peer cannot survive stop.
      destroySocket(socket);
      return;
    }
    const state = { responded: false, buffer: Buffer.alloc(0), deadline: null };
    connections.set(socket, state);
    const clearDeadline = () => {
      if (state.deadline) {
        clearTimeout(state.deadline);
        state.deadline = null;
      }
    };
    const finish = () => {
      clearDeadline();
      connections.delete(socket);
    };
    const respond = (line) => {
      if (state.responded) return;
      state.responded = true;
      // Queue the reply but keep the absolute deadline running: a completed
      // request whose peer keeps its write half open still owns a socket
      // slot until the socket actually closes.
      try {
        socket.end(`${line}\n`);
      } catch (_) {}
    };
    state.deadline = setTimeout(() => {
      state.deadline = null;
      // The deadline bounds the whole socket lifetime, not only the request
      // read. Tear down on timeout whether or not a response was already
      // queued so a half-open client cannot retain a connection slot.
      state.responded = true;
      destroySocket(socket);
    }, requestDeadlineMs);
    if (state.deadline && typeof state.deadline.unref === "function") {
      state.deadline.unref();
    }
    socket.on("close", finish);
    socket.on("data", (chunk) => {
      if (state.responded) return;
      const bytes = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
      // The cap counts actual bytes, not Unicode code units, and is checked
      // before concatenation so the buffer itself stays bounded.
      if (state.buffer.length + bytes.length > BROKER_MAX_REQUEST_BYTES) {
        respond(
          JSON.stringify({ v: BROKER_PROTOCOL_VERSION, ok: false, error: "request too large" }),
        );
        return;
      }
      state.buffer = Buffer.concat([state.buffer, bytes]);
      const newline = state.buffer.indexOf(0x0a);
      if (newline < 0) return;
      const line = state.buffer.subarray(0, newline).toString("utf8");
      let reply;
      try {
        reply = handle(line);
      } catch (_) {
        reply = JSON.stringify({ v: BROKER_PROTOCOL_VERSION, ok: false, error: "malformed request" });
      }
      respond(reply);
    });
  }

  // Bind the loopback interface on an ephemeral port. The address is
  // `127.0.0.1:<port>` and never leaves the machine. A listener that cannot
  // bind fails closed: `start` resolves `null` with no endpoint, so the
  // bridge still marks a managed shell with the session and no credential and
  // the CLI refuses the role instead of becoming an ordinary operator CLI.
  async function start() {
    if (address) return address;
    return new Promise((resolve) => {
      const listener = net.createServer(serve);
      let settled = false;
      const fail = () => {
        if (settled) return;
        settled = true;
        try {
          listener.close();
        } catch (_) {}
        server = null;
        address = null;
        resolve(null);
      };
      listener.on("error", fail);
      listener.listen(0, "127.0.0.1", () => {
        if (settled) return;
        const bound = listener.address();
        if (!bound || typeof bound === "string") {
          fail();
          return;
        }
        settled = true;
        server = listener;
        address = `127.0.0.1:${bound.port}`;
        resolve(address);
      });
    });
  }

  function stop() {
    for (const [socket, state] of connections) {
      if (state.deadline) {
        clearTimeout(state.deadline);
        state.deadline = null;
      }
      destroySocket(socket);
    }
    connections.clear();
    if (server) {
      try {
        server.close();
      } catch (_) {
        // closing a broker must never break the host
      }
      server = null;
    }
    address = null;
    entries.clear();
  }

  function size() {
    pruneExpired(now());
    return entries.size;
  }

  function connectionCount() {
    return connections.size;
  }

  return {
    mint,
    revokeToolCall,
    handle,
    start,
    stop,
    size,
    connectionCount,
    address: () => address,
    _entries: entries,
    _connections: connections,
    _ttlMs: ttlMs,
    _maxEntries: maxEntries,
    _maxConnections: maxConnections,
    _requestDeadlineMs: requestDeadlineMs,
  };
}

// assets/opencode/src/managed-env.js
// Managed shell execution bridge (issue #859 P1; issue #22 P1 verified
// identity).
//
// Per-plugin-instance correlation between `tool.execute.before` and
// `shell.create.before` via an opaque unique per-tool-call nonce, not a
// command FIFO and not command-only matching.
//
// Flow:
//   1. `tool.execute.before` first performs the existing phasegent command
//      rewrite (`rewritePhasegentCommand`), then the bridge stores
//      `{ nonce, sessionID, token, toolCallId, expected, timestamp }` where
//      `expected` is the exact header-prefixed command, and prepends one
//      POSIX/PowerShell-safe comment line `# phasegent-context:<nonce>\n`.
//      The header is inert in both shells and never an identity claim.
//   2. `shell.create.before` consumes only on exact nonce plus exact
//      decorated-command match, once. It strips only its own leading line,
//      restores the exact rewritten bytes, and mutates the fresh `event.env`
//      properties only: the host broker endpoint and the opaque broker token
//      of the live tool call, plus `PHASEGENT_SESSION_ID` with the real tool
//      session. A real session id is required; without one the bridge
//      decorates nothing.
//   3. `tool.execute.after` evicts by tool call id so cancelled or failed
//      calls never leak, and revokes the broker credentials of the call.
//      Bounded TTL (5 minutes) and capacity (64 entries) evict lazily; an
//      evicted entry only deletes, never reuses or pairs. A lost entry falls
//      back to the host native `OPENCODE_SESSION_ID` marker rejection, never
//      a guessed identity.
//
// The role never travels in the command text: the CLI reads it from the
// host broker, which derived it from the host facts it stored.
//
// No global `process.env` mutation, no FIFO, no mutable cross-session current
// role. Expired, replayed, forged, or mismatched headers never provide an
// identity. No full commands or secret data are logged; warnings stay generic.


const MANAGED_CONTEXT_PREFIX = "# phasegent-context:";
// The legacy role variable. The plugin never sets it any more; the bridge
// removes an inherited one so a stale role claim never reaches the CLI.
const MANAGED_ROLE_ENV = "PHASEGENT_ROLE";
const MANAGED_SESSION_ENV = "PHASEGENT_SESSION_ID";
const MANAGED_BRIDGE_CAPACITY = 64;
const MANAGED_BRIDGE_TTL_MS = 5 * 60 * 1000;

const NONCE_PATTERN = /^[A-Za-z0-9._:-]{1,128}$/;

function defaultNow() {
  return Date.now();
}

function defaultRandomUUID() {
  try {
    const cryptoObject =
      (typeof globalThis !== "undefined" && globalThis.crypto) || null;
    if (cryptoObject && typeof cryptoObject.randomUUID === "function") {
      return cryptoObject.randomUUID();
    }
  } catch (_) {
    // fall through to deterministic fallback below
  }
  // Fallback is only reached where `crypto.randomUUID` is unavailable; it is
  // never used to reuse a live nonce because every generated value is stored
  // and checked for collision before use.
  const random = Math.floor(Math.random() * 0xffffffff);
  const time = Date.now() & 0xffffffff;
  return `fallback-${time.toString(16)}-${random.toString(16)}`;
}

function isNonEmptyString(value) {
  return typeof value === "string" && value.length > 0;
}

// A credential can only be revoked by its host tool-call id, so a missing,
// null, or blank id never receives one.
function isUsableLifecycleId(value) {
  return typeof value === "string" && value.trim().length > 0;
}

// Capability probe: the host must expose `context.shell.hook` before the
// bridge decorates anything with an identity promise. A missing surface
// degrades to the existing rewrite-only path with an explicit warning.
function isShellHookSupported(context) {
  return Boolean(
    context && context.shell && typeof context.shell.hook === "function",
  );
}

function isToolAfterHookSupported(context) {
  return Boolean(
    context && context.tool && typeof context.tool.hook === "function",
  );
}

// Parse the leading `# phasegent-context:<nonce>\n` header. Returns the nonce
// string, or null when the command carries no well-formed bridge header.
function parseManagedNonce(command) {
  if (typeof command !== "string") return null;
  if (!command.startsWith(MANAGED_CONTEXT_PREFIX)) return null;
  const newline = command.indexOf("\n");
  if (newline < 0) return null;
  const nonce = command.slice(MANAGED_CONTEXT_PREFIX.length, newline).trim();
  if (!NONCE_PATTERN.test(nonce)) return null;
  return nonce;
}

function managedHeaderFor(nonce) {
  return `${MANAGED_CONTEXT_PREFIX}${nonce}\n`;
}

// Per-setup bridge factory. Options are injectable for deterministic tests:
// `{ now, randomUUID, capacity, ttlMs, broker }`. Each setup call owns an
// isolated Map; no module-global state is shared across plugin instances.
//
// The broker is the identity authority: the bridge mints one opaque
// credential per tool call through it and hands the endpoint and the token
// to the shell through the fresh env. Without a broker the bridge still
// marks the shell as managed, so the CLI fails closed instead of becoming
// an ordinary operator CLI.
function createManagedShellBridge(options) {
  const now =
    options && typeof options.now === "function" ? options.now : defaultNow;
  const randomUUID =
    options && typeof options.randomUUID === "function"
      ? options.randomUUID
      : defaultRandomUUID;
  const capacity =
    options && typeof options.capacity === "number" && options.capacity > 0
      ? Math.floor(options.capacity)
      : MANAGED_BRIDGE_CAPACITY;
  const ttlMs =
    options && typeof options.ttlMs === "number" && options.ttlMs >= 0
      ? options.ttlMs
      : MANAGED_BRIDGE_TTL_MS;
  const broker =
    options && options.broker && typeof options.broker === "object"
      ? options.broker
      : null;

  // nonce -> { nonce, sessionID, token, toolCallId, expected, timestamp }
  // Insertion order is the eviction order: the oldest entry is discarded
  // first when capacity is reached. Entries are never reused or re-paired.
  const entries = new Map();

  function pruneExpired(current) {
    for (const [nonce, entry] of entries) {
      if (current - entry.timestamp > ttlMs) {
        entries.delete(nonce);
      }
    }
  }

  function evictOldestIfNeeded() {
    while (entries.size >= capacity) {
      const oldest = entries.keys().next();
      if (oldest.done) break;
      entries.delete(oldest.value);
    }
  }

  function generateNonce() {
    // A stored nonce is never reused: on the vanishingly unlikely collision
    // the generator retries instead of overwriting the live entry.
    for (let attempt = 0; attempt < 8; attempt += 1) {
      const candidate = String(randomUUID());
      if (!NONCE_PATTERN.test(candidate)) continue;
      if (!entries.has(candidate)) return candidate;
    }
    return null;
  }

  // Store one tool call and return the header-prefixed command. Returns the
  // input unchanged when decoration is impossible (missing session id or
  // unusable nonce); the caller keeps the rewrite-only path in that case.
  function decorate(rewritten, sessionID, role, toolCallId) {
    if (typeof rewritten !== "string") return rewritten;
    if (!isNonEmptyString(sessionID)) return rewritten;
    const current = now();
    pruneExpired(current);
    const nonce = generateNonce();
    if (!nonce) return rewritten;
    evictOldestIfNeeded();
    const header = managedHeaderFor(nonce);
    const expected = `${header}${rewritten}`;
    // The broker mints the opaque credential of this tool call and keeps
    // the host facts; the role never leaves the plugin. A broker that is
    // absent, refuses (capacity), fails, or has no usable lifecycle id still
    // leaves the command marked as managed: the shell then carries the
    // session marker without a usable credential, so the CLI fails closed
    // instead of becoming an ordinary operator CLI.
    const lifecycleId = isUsableLifecycleId(toolCallId) ? toolCallId : null;
    let token = null;
    if (lifecycleId) {
      try {
        token =
          broker && typeof broker.mint === "function"
            ? broker.mint(role, sessionID, lifecycleId)
            : null;
      } catch (_) {
        token = null;
      }
    }
    entries.set(nonce, {
      nonce,
      sessionID,
      token: isNonEmptyString(token) ? token : null,
      toolCallId: lifecycleId,
      expected,
      timestamp: current,
    });
    return expected;
  }

  // Consume one shell invocation. On exact nonce plus exact decorated-command
  // match with a live entry, strips the header, restores the exact rewritten
  // bytes, mutates only `event.env` properties, deletes the entry (single
  // use), and returns `{ consumed: true }`. Every other shape — missing,
  // forged, mismatched, expired, or replayed — leaves `event.command` and
  // `event.env` untouched and returns `{ consumed: false }` without logging
  // command bytes.
  function consume(shellEvent) {
    if (!shellEvent || typeof shellEvent.command !== "string") {
      return { consumed: false, reason: "missing-command" };
    }
    const nonce = parseManagedNonce(shellEvent.command);
    if (!nonce) return { consumed: false, reason: "no-header" };
    const current = now();
    const entry = entries.get(nonce);
    if (!entry) return { consumed: false, reason: "unknown-nonce" };
    // Single use: the entry is removed before any further check so a replay
    // can never pair again, even on mismatch.
    entries.delete(nonce);
    if (current - entry.timestamp > ttlMs) {
      return { consumed: false, reason: "expired" };
    }
    if (shellEvent.command !== entry.expected) {
      return { consumed: false, reason: "mismatch" };
    }
    const rewritten = shellEvent.command.slice(
      managedHeaderFor(nonce).length,
    );
    shellEvent.command = rewritten;
    let env = shellEvent.env;
    if (!env || typeof env !== "object") {
      env = {};
      shellEvent.env = env;
    }
    try {
      // The shell receives the broker endpoint and the opaque credential of
      // this tool call. A stale inherited endpoint, token, or role claim is
      // removed first, so a shell never verifies against another call's
      // facts.
      delete env[BROKER_ADDR_ENV];
      delete env[BROKER_TOKEN_ENV];
      delete env[MANAGED_ROLE_ENV];
      if (entry.token) {
        const address =
          broker && typeof broker.address === "function" ? broker.address() : null;
        if (isNonEmptyString(address)) {
          env[BROKER_ADDR_ENV] = address;
          env[BROKER_TOKEN_ENV] = entry.token;
        }
      }
      env[MANAGED_SESSION_ENV] = entry.sessionID;
    } catch (_) {
      return { consumed: false, reason: "env-failed" };
    }
    return { consumed: true, nonce, sessionID: entry.sessionID };
  }

  function cleanupByToolCallId(toolCallId) {
    if (!isNonEmptyString(toolCallId)) return 0;
    let removed = 0;
    for (const [nonce, entry] of entries) {
      if (entry.toolCallId === toolCallId) {
        entries.delete(nonce);
        removed += 1;
      }
    }
    // The call is over: its broker credential is revoked too, so a later
    // invocation cannot reuse the finished call's identity.
    if (broker && typeof broker.revokeToolCall === "function") {
      broker.revokeToolCall(toolCallId);
    }
    // Lazy expiry keeps the map bounded even when after-hooks never fire
    // (for example a cancelled tool call whose after event is unproven).
    pruneExpired(now());
    return removed;
  }

  function size() {
    pruneExpired(now());
    return entries.size;
  }

  function clear() {
    entries.clear();
  }

  return {
    decorate,
    consume,
    cleanupByToolCallId,
    size,
    clear,
    // Test-only introspection without exposing command bytes in logs.
    _entries: entries,
    _capacity: capacity,
    _ttlMs: ttlMs,
  };
}

// `shell.create.before` hook factory: property-only `event.command` /
// `event.env` edits, no global env mutation, no identity on failure.
function createShellEnvHook(bridge) {
  return async function shellCreateBefore(event) {
    if (!event || typeof event.command !== "string") return;
    if (!bridge || typeof bridge.consume !== "function") return;
    try {
      bridge.consume(event);
    } catch (_) {
      // Never throw into a tool call; a failed consume simply leaves the
      // command and env untouched so the host marker fails closed.
    }
  };
}

// `tool.execute.after` hook factory: evicts by tool call id so cancelled or
// failed calls never leak. Carries no identity and logs no command data.
function createToolAfterHook(bridge) {
  return async function executeAfter(event) {
    if (!event || !bridge || typeof bridge.cleanupByToolCallId !== "function") {
      return;
    }
    try {
      const toolCallId =
        typeof event.id === "string"
          ? event.id
          : event && event.input && typeof event.input === "object"
            ? null
            : null;
      // The host carries the same `id` on before and after for one tool
      // call; fall back to scanning nothing when the shape is unknown.
      if (toolCallId) bridge.cleanupByToolCallId(toolCallId);
    } catch (_) {
      // ignore: cleanup must never break a tool call
    }
  };
}

// assets/opencode/src/scanner.js
// Quote-aware shell scanning (issue #541 P1; heredoc-opaque issue #859 P2).
//
// Inside `'…'` or `"…"` a separator is data, not syntax, and outside single
// quotes a backslash escapes the next character. An unterminated quote owns
// the rest of the text.
//
// Heredoc bodies (`<<` / `<<-` with quoted, unquoted, or quote-removed
// delimiters, multiple queued bodies in order) are opaque data: body bytes
// (apostrophes, quotes, semicolons, `phasegent` look-alikes, role claims)
// never pollute quote state, never split segments, and never rewrite.
// Here-strings (`<<<`) are not heredocs. Operators inside quoted strings or
// `#` comments are not declarations. Unterminated heredocs and ambiguous
// quote shapes conservatively preserve the affected text and rely on the
// execution-layer role/marker instead of inventing shell semantics.

function skipQuoted(text, start) {
  const quote = text[start];
  let index = start + 1;
  while (index < text.length) {
    const char = text[index];
    if (quote === '"' && char === "\\") {
      index += 2;
      continue;
    }
    if (char === quote) return index + 1;
    index += 1;
  }
  return -1;
}

function isCommentStart(text, index) {
  if (text[index] !== "#") return false;
  if (index === 0) return true;
  const prev = text[index - 1];
  return (
    prev === " " ||
    prev === "\t" ||
    prev === "\n" ||
    prev === ";" ||
    prev === "&" ||
    prev === "|" ||
    prev === "("
  );
}

function isHeredocWordTerminator(char) {
  return (
    char === undefined ||
    char === " " ||
    char === "\t" ||
    char === "\n" ||
    char === ";" ||
    char === "&" ||
    char === "|" ||
    char === "(" ||
    char === ")" ||
    char === "<" ||
    char === ">" ||
    char === "#"
  );
}

// Scan one delimiter word starting at `pos` (after `<<[-]` plus blanks).
// Returns `{ value, end }` where `value` is the quote-removed delimiter for
// terminator comparison and `end` is the index after the word in original
// bytes, or null when there is no usable delimiter (unsupported shape).
function parseHeredocDelimiter(text, pos) {
  const n = text.length;
  if (pos >= n || isHeredocWordTerminator(text[pos])) return null;
  let value = "";
  let index = pos;
  while (index < n && !isHeredocWordTerminator(text[index])) {
    const char = text[index];
    if (char === "'") {
      const close = text.indexOf("'", index + 1);
      // Unterminated quote inside the delimiter: ambiguous, not a heredoc.
      // Also reject a closing quote that runs past the word (newline).
      if (close < 0) return null;
      const newlineBeforeClose = text.indexOf("\n", index + 1);
      if (newlineBeforeClose >= 0 && newlineBeforeClose < close) return null;
      value += text.slice(index + 1, close);
      index = close + 1;
      continue;
    }
    if (char === '"') {
      let cursor = index + 1;
      let inner = "";
      let closed = false;
      while (cursor < n) {
        const innerChar = text[cursor];
        if (innerChar === "\\" && cursor + 1 < n && text[cursor + 1] !== "\n") {
          inner += text[cursor + 1];
          cursor += 2;
          continue;
        }
        if (innerChar === '"') {
          closed = true;
          cursor += 1;
          break;
        }
        if (innerChar === "\n") break;
        inner += innerChar;
        cursor += 1;
      }
      if (!closed) return null;
      value += inner;
      index = cursor;
      continue;
    }
    if (char === "\\") {
      if (index + 1 >= n || text[index + 1] === "\n") return null;
      value += text[index + 1];
      index += 2;
      continue;
    }
    value += char;
    index += 1;
  }
  if (value.length === 0) return null;
  return { value, end: index };
}

function terminatorLineMatches(text, lineStart, lineEnd, delimiter, stripTabs) {
  // Strip a trailing `\r` for `CRLF` scripts without changing byte offsets:
  // matching uses content without `\r`, ranges still cover it.
  let contentEnd = lineEnd;
  if (contentEnd > lineStart && text[contentEnd - 1] === "\r") contentEnd -= 1;
  let pos = lineStart;
  if (stripTabs) {
    while (pos < contentEnd && text[pos] === "\t") pos += 1;
  } else if (pos < contentEnd && (text[pos] === " " || text[pos] === "\t")) {
    return false;
  }
  if (pos + delimiter.length !== contentEnd) return false;
  return text.slice(pos, pos + delimiter.length) === delimiter;
}

// Shared lexical scan: opaque heredoc ranges (delimiter words plus bodies
// with terminator lines, excluding the final newline so the terminator
// newline still separates commands). Sorted, non-overlapping. Empty when
// there is no `<<` heredoc declaration in code.
function scanHeredocRanges(text) {
  const ranges = [];
  const n = text.length;
  if (!text.includes("<<")) return ranges;
  let index = 0;
  let inSingle = false;
  let inDouble = false;
  let inComment = false;
  // Declarations collected on the current logical line (before its newline).
  let pending = [];
  // Delimiter word ranges for the current line (pushed immediately so quote
  // removal literals in data stay untouched by later transforms).
  const pushRange = (start, end) => {
    if (end > start) ranges.push({ start, end });
  };

  const consumePendingBodies = (newlineIndex) => {
    // Called on an unescaped, unquoted newline with pending declarations.
    // The declaration newline itself is heredoc syntax (not a separator), so
    // the first body range includes it; intermediate terminator newlines are
    // included to keep queued bodies contiguous, while the final terminator
    // newline stays outside so it still separates the following command.
    let bodyPos = newlineIndex;
    for (let declIndex = 0; declIndex < pending.length; declIndex += 1) {
      const decl = pending[declIndex];
      const isLast = declIndex === pending.length - 1;
      const bodyStart = bodyPos;
      const searchFrom = declIndex === 0 ? newlineIndex + 1 : bodyPos;
      let lineStart = searchFrom;
      let found = false;
      while (lineStart <= n) {
        if (lineStart >= n) {
          // Unterminated: rest is opaque body, no terminator.
          pushRange(bodyStart, n);
          bodyPos = n;
          found = false;
          break;
        }
        const newlineAt = text.indexOf("\n", lineStart);
        const lineEnd = newlineAt < 0 ? n : newlineAt;
        if (terminatorLineMatches(text, lineStart, lineEnd, decl.delimiter, decl.stripTabs)) {
          if (isLast) {
            pushRange(bodyStart, lineEnd);
            bodyPos = newlineAt < 0 ? n : newlineAt + 1;
          } else {
            pushRange(bodyStart, newlineAt < 0 ? n : newlineAt + 1);
            bodyPos = newlineAt < 0 ? n : newlineAt + 1;
          }
          found = true;
          break;
        }
        lineStart = newlineAt < 0 ? n : newlineAt + 1;
      }
      if (!found && bodyPos >= n) {
        // Unterminated rest already pushed; remaining queued bodies share it.
        break;
      }
    }
    pending = [];
    return bodyPos;
  };

  while (index < n) {
    const char = text[index];
    if (inComment) {
      if (char === "\n") {
        inComment = false;
        // A comment newline ends the line: bodies follow if declarations
        // preceded the comment on the same line (e.g. `cat <<EOF # comment`).
        if (pending.length > 0 && !inSingle && !inDouble) {
          const next = consumePendingBodies(index);
          // Skip the opaque bodies (and terminators) without re-scanning
          // their quotes, separators, or fake declarations.
          index = next;
          continue;
        }
      }
      index += 1;
      continue;
    }
    if (inSingle) {
      if (char === "'") inSingle = false;
      index += 1;
      continue;
    }
    if (inDouble) {
      if (char === "\\" && index + 1 < n) {
        index += 2;
        continue;
      }
      if (char === '"') inDouble = false;
      index += 1;
      continue;
    }
    // In code.
    if (char === "\\" && index + 1 < n) {
      // Escaped char (including an escaped newline line-continuation):
      // never an operator, quote, or line end.
      index += 2;
      continue;
    }
    if (char === "'") {
      inSingle = true;
      index += 1;
      continue;
    }
    if (char === '"') {
      inDouble = true;
      index += 1;
      continue;
    }
    if (char === "#" && isCommentStart(text, index)) {
      inComment = true;
      index += 1;
      continue;
    }
    if (char === "<" && text[index + 1] === "<") {
      if (text[index + 2] === "<") {
        // Here-string `<<<`: not a heredoc, skip the operator.
        index += 3;
        continue;
      }
      let cursor = index + 2;
      let stripTabs = false;
      if (text[cursor] === "-") {
        stripTabs = true;
        cursor += 1;
      }
      let blank = cursor;
      while (blank < n && (text[blank] === " " || text[blank] === "\t")) blank += 1;
      const parsed = parseHeredocDelimiter(text, blank);
      if (!parsed) {
        // Unsupported shape (`<<` with no word, empty removal, or
        // unterminated quote in the word): not a heredoc, keep bytes.
        index += 2 + (stripTabs ? 1 : 0);
        continue;
      }
      // Valid declaration on this line: queue its body, mark its word opaque.
      pending.push({ delimiter: parsed.value, stripTabs });
      pushRange(blank, parsed.end);
      index = parsed.end;
      continue;
    }
    if (char === "\n") {
      if (pending.length > 0) {
        const next = consumePendingBodies(index);
        index = next;
        continue;
      }
      index += 1;
      continue;
    }
    index += 1;
  }
  ranges.sort((a, b) => a.start - b.start);
  return ranges;
}

// Replace every quoted run (and escaped character) with spaces of the same
// length: offsets still line up with the original command, and a quoted value
// can never be read as a flag. `balanced` is false when a quote is never closed.
// Heredoc bodies and delimiter words are opaque first, so an apostrophe in
// data never starts a quote that swallows a real invocation.
function maskQuoted(text) {
  const heredoc = scanHeredocRanges(text);
  let masked = "";
  let index = 0;
  let balanced = true;
  let heredocPos = 0;
  const skipHeredoc = () => {
    while (heredocPos < heredoc.length && index >= heredoc[heredocPos].end) heredocPos += 1;
    if (heredocPos < heredoc.length) {
      const range = heredoc[heredocPos];
      if (index >= range.start && index < range.end) return range;
    }
    return null;
  };
  while (index < text.length) {
    const opaque = skipHeredoc();
    if (opaque) {
      masked += " ".repeat(opaque.end - index);
      index = opaque.end;
      continue;
    }
    const char = text[index];
    if (char === "'" || char === '"') {
      const end = skipQuoted(text, index);
      if (end < 0) {
        masked += " ".repeat(text.length - index);
        balanced = false;
        break;
      }
      masked += " ".repeat(end - index);
      index = end;
      continue;
    }
    if (char === "\\") {
      const width = index + 1 < text.length ? 2 : 1;
      masked += " ".repeat(width);
      index += width;
      continue;
    }
    masked += char;
    index += 1;
  }
  return { masked, balanced };
}

// Apply `transform` to the code spans only; quoted runs, escaped characters,
// and heredoc bodies/delimiters stay byte-for-byte, so a rewrite never lands
// inside a value or data.
function transformCodeOnly(text, transform) {
  const heredoc = scanHeredocRanges(text);
  let result = "";
  let cursor = 0;
  let index = 0;
  let heredocPos = 0;
  const opaqueAt = () => {
    while (heredocPos < heredoc.length && index >= heredoc[heredocPos].end) heredocPos += 1;
    if (heredocPos < heredoc.length) {
      const range = heredoc[heredocPos];
      if (index >= range.start && index < range.end) return range;
    }
    return null;
  };
  while (index < text.length) {
    const opaque = opaqueAt();
    if (opaque) {
      result += transform(text.slice(cursor, index)) + text.slice(index, opaque.end);
      cursor = opaque.end;
      index = opaque.end;
      continue;
    }
    const char = text[index];
    if (char === "'" || char === '"') {
      const end = skipQuoted(text, index);
      if (end < 0) {
        result += transform(text.slice(cursor, index)) + text.slice(index);
        cursor = text.length;
        break;
      }
      result += transform(text.slice(cursor, index)) + text.slice(index, end);
      cursor = end;
      index = end;
      continue;
    }
    if (char === "\\") {
      index += 2;
      continue;
    }
    index += 1;
  }
  return result + transform(text.slice(cursor));
}

function separatorAt(command, index) {
  const pair = command.slice(index, index + 2);
  if (pair === "&&" || pair === "||") return pair;
  const char = command[index];
  if (char === "&") {
    // Redirection, not a segment boundary: `&>`/`&>>` (the `&` sits before
    // `>`) and `N>&M`/`>&N`/`<&N` (the `&` sits after `>`/`<`). Only a
    // standalone `&` is the background separator (issue #544 P1-b).
    if (command[index + 1] === ">" || command[index - 1] === ">" || command[index - 1] === "<") {
      return null;
    }
    return "&";
  }
  if (char === ";" || char === "|" || char === "(" || char === ")" || char === "\n") {
    return char;
  }
  return null;
}

function shellSegments(command) {
  const heredoc = scanHeredocRanges(command);
  let heredocPos = 0;
  const opaqueAt = (pos) => {
    while (heredocPos < heredoc.length && pos >= heredoc[heredocPos].end) heredocPos += 1;
    // Note: `heredocPos` advances monotonically with `pos` because callers
    // only move forward; ranges are sorted so this stays consistent.
    for (const range of heredoc) {
      if (pos >= range.start && pos < range.end) return range;
    }
    return null;
  };
  const segments = [];
  let cursor = 0;
  let index = 0;
  while (index < command.length) {
    const opaque = opaqueAt(index);
    if (opaque) {
      index = opaque.end;
      continue;
    }
    const char = command[index];
    if (char === "'" || char === '"') {
      const end = skipQuoted(command, index);
      if (end < 0) break; // unterminated quote: the rest belongs to this segment
      index = end;
      continue;
    }
    if (char === "\\") {
      index += 2;
      continue;
    }
    const separator = separatorAt(command, index);
    if (separator === null) {
      index += 1;
      continue;
    }
    if (index > cursor) {
      segments.push({ start: cursor, end: index, text: command.slice(cursor, index) });
    }
    cursor = index + separator.length;
    index = cursor;
    // A separator may land inside a heredoc terminator gap? No: heredoc
    // ranges exclude the terminator newline, so the newline after the
    // terminator is a real separator and correctly splits here.
    heredocPos = 0;
  }
  if (cursor < command.length) {
    segments.push({ start: cursor, end: command.length, text: command.slice(cursor) });
  }
  return segments;
}

// One whitespace-delimited word of the masked segment starting at `pos`.
// Quoted runs are already blanks in `masked`, so a value can never be read as
// a flag; offsets stay aligned with the original segment.
function nextShellToken(masked, pos) {
  const n = masked.length;
  let index = pos;
  while (index < n && (masked[index] === " " || masked[index] === "\t")) index += 1;
  if (index >= n) return null;
  let end = index;
  while (end < n && masked[end] !== " " && masked[end] !== "\t") end += 1;
  return { word: masked.slice(index, end), start: index, end };
}

const ASSIGNMENT_WORD = /^[A-Za-z_][A-Za-z0-9_]*\+?=/;

// `timeout` option tail: bounded arity before its command word. `null` means
// an unsupported/ambiguous shape, so the caller leaves the bytes untouched.
function parseTimeoutWrapper(masked, pos) {
  let index = pos;
  let durationSeen = false;
  for (let guard = 0; guard < 32; guard += 1) {
    const token = nextShellToken(masked, index);
    if (!token) return null;
    const word = token.word;
    if (word === "--") {
      return durationSeen ? token.end : null;
    }
    if (word === "-s" || word === "--signal" || word === "-k" || word === "--kill-after") {
      const value = nextShellToken(masked, token.end);
      if (!value) return null;
      index = value.end;
      continue;
    }
    if (word.startsWith("--signal=") || word.startsWith("--kill-after=")) {
      index = token.end;
      continue;
    }
    if (
      word === "--preserve-status" ||
      word === "--foreground" ||
      word === "-v" ||
      word === "--verbose"
    ) {
      index = token.end;
      continue;
    }
    if (word.startsWith("-")) return null;
    if (!durationSeen) {
      durationSeen = true;
      index = token.end;
      continue;
    }
    return token.start;
  }
  return null;
}

// `env` option/assignment tail up to its command word (or null when
// unsupported).
function parseEnvWrapper(masked, pos) {
  let index = pos;
  for (let guard = 0; guard < 64; guard += 1) {
    const token = nextShellToken(masked, index);
    if (!token) return null;
    const word = token.word;
    if (word === "-i" || word === "--ignore-environment" || word === "--null") {
      index = token.end;
      continue;
    }
    if (
      word === "-u" ||
      word === "--unset" ||
      word === "-C" ||
      word === "--chdir" ||
      word === "-S" ||
      word === "--split-string"
    ) {
      const value = nextShellToken(masked, token.end);
      if (!value) return null;
      index = value.end;
      continue;
    }
    if (
      word.startsWith("--unset=") ||
      word.startsWith("--chdir=") ||
      word.startsWith("--split-string=")
    ) {
      index = token.end;
      continue;
    }
    if (ASSIGNMENT_WORD.test(word)) {
      index = token.end;
      continue;
    }
    if (word.startsWith("-")) return null;
    return token.start;
  }
  return null;
}

// Bounded POSIX transparent wrappers (`timeout`, `env`, `command`) plus
// assignment words before the actual command name (issue #917 P1). Returns the
// byte offset where the command word starts and whether any wrapper was
// crossed; `null` means an unsupported/ambiguous shape, so the invocation is
// left byte-for-byte instead of guessing shell semantics.
function parseWrappers(masked, pos) {
  let index = pos;
  let wrapped = false;
  for (let guard = 0; guard < 16; guard += 1) {
    const token = nextShellToken(masked, index);
    if (!token) return null;
    if (ASSIGNMENT_WORD.test(token.word)) {
      index = token.end;
      continue;
    }
    if (token.word === "timeout") {
      const after = parseTimeoutWrapper(masked, token.end);
      if (after === null) return null;
      index = after;
      wrapped = true;
      continue;
    }
    if (token.word === "env") {
      const after = parseEnvWrapper(masked, token.end);
      if (after === null) return null;
      index = after;
      wrapped = true;
      continue;
    }
    if (token.word === "command") {
      // `command -v`/`-V` are lookups, not executions: any option makes the
      // shape ambiguous, so it stays untouched.
      const next = nextShellToken(masked, token.end);
      if (!next || next.word.startsWith("-")) return null;
      index = token.end;
      wrapped = true;
      continue;
    }
    return { pos: token.start, wrapped };
  }
  return null;
}

// Split one shell segment into words while respecting quotes (issue #22 P3).
// Each word keeps its raw bytes and a quote-removed `value`, so a caller can
// recognise an assignment name written as `"PHASEGENT_ROLE"=…` without ever
// reading a quoted value as syntax. Words never cross an unquoted space or tab;
// quoting only joins bytes inside one word.
function unquoteShellWord(raw) {
  let value = "";
  let index = 0;
  while (index < raw.length) {
    const char = raw[index];
    if (char === "'") {
      const end = raw.indexOf("'", index + 1);
      if (end < 0) {
        value += raw.slice(index + 1);
        break;
      }
      value += raw.slice(index + 1, end);
      index = end + 1;
      continue;
    }
    if (char === '"') {
      let cursor = index + 1;
      while (cursor < raw.length && raw[cursor] !== '"') {
        if (raw[cursor] === "\\" && cursor + 1 < raw.length) {
          const next = raw[cursor + 1];
          if (next === '"' || next === "\\" || next === "$" || next === "`") {
            value += next;
            cursor += 2;
            continue;
          }
        }
        value += raw[cursor];
        cursor += 1;
      }
      index = cursor + 1;
      continue;
    }
    if (char === "\\" && index + 1 < raw.length) {
      value += raw[index + 1];
      index += 2;
      continue;
    }
    value += char;
    index += 1;
  }
  return value;
}

function shellWords(text) {
  const words = [];
  let index = 0;
  const n = text.length;
  while (index < n) {
    while (index < n && (text[index] === " " || text[index] === "\t")) index += 1;
    if (index >= n) break;
    const start = index;
    let raw = "";
    while (index < n && text[index] !== " " && text[index] !== "\t") {
      if (text[index] === "'" || text[index] === '"') {
        const end = skipQuoted(text, index);
        if (end < 0) {
          raw += text.slice(index);
          index = n;
          break;
        }
        raw += text.slice(index, end);
        index = end;
        continue;
      }
      if (text[index] === "\\" && index + 1 < n) {
        raw += text.slice(index, index + 2);
        index += 2;
        continue;
      }
      raw += text[index];
      index += 1;
    }
    words.push({ start, end: index, raw, value: unquoteShellWord(raw) });
  }
  return words;
}

function phasegentInvocation(segment) {
  const { masked, balanced } = maskQuoted(segment.text);
  let text = segment.text;
  let offset = segment.start;
  const leading = text.match(/^\s+/);
  if (leading) {
    offset += leading[0].length;
    text = text.slice(leading[0].length);
  }
  const env = text.match(/^(?:[A-Za-z_][A-Za-z0-9_]*=(?:"[^"]*"|'[^']*'|\S+)\s+)+/);
  if (env) {
    offset += env[0].length;
    text = text.slice(env[0].length);
  }
  // Transparent wrappers (`timeout 40s env FOO=1 phasegent …`) sit between the
  // leading assignments and the command name. The wrapper context is recorded
  // so the rewrite can inject a valid invocation-local env (`timeout … env
  // PHASEGENT_ROLE=… phasegent`), which an assignment inserted as an
  // executable would not be.
  const wrappers = parseWrappers(masked, offset - segment.start);
  if (wrappers === null) return null;
  const wrapped = wrappers.wrapped;
  offset = segment.start + wrappers.pos;
  text = segment.text.slice(wrappers.pos);
  // The command name must be a whole word followed by whitespace or the
  // segment end, and the prefix slot excludes quotes and backticks: `\b` also
  // matched before `-`/`.`/`:`/`/`, so a quoted path such as
  // `assets/opencode/phasegent-worktree.js` was rewritten as a call
  // (issue #544 P1-a).
  const token = text.match(/^(?:[^\s;&|()'"`]*\/)?phasegent(?=\s|$)/);
  if (!token) return null;
  const trailing = text.length - text.trimEnd().length;
  return {
    tokenEnd: offset + token[0].length,
    segmentEnd: segment.end - trailing,
    tail: masked.slice(offset - segment.start + token[0].length),
    balanced,
    wrapped,
  };
}

// assets/opencode/src/command.js
// Shell command rewriting for `phasegent` invocations (issue #541; issue #588
// phase 2; issue #22 P1 verified identity; issue #22 P3 visible-mutation guard).
//
// The session role is never written into the command text: a self-selected
// variable could always claim any identity, so the role travels out of band
// through the host broker, which derived it from the facts the host reported
// for the tool call. The rewrite keeps the two session-bound flags
// (`issue create --session`, `issue close --worktree-session`) and the
// sub-agent refusal of the orchestrator-only `issue create`/`bind`.
//
// The same funnel refuses any visible mutation of the managed identity and
// transport variables before execution. An inline assignment, `export`,
// `unset`, a mutating builtin (`builtin unset`, `read`, `printf -v`, ...), or
// an `env` override could otherwise replace the broker endpoint the bridge
// injected (or strip every managed marker and become an Operator), so no part
// of the hooked command may mutate them. Redirection operands are consumed so
// `> /dev/null unset ...` cannot hide the mutation behind a filename. The guard
// scans the whole command, not only the phasegent segment, because an `unset`
// in an earlier segment and the phasegent call in a later one are separate
// commands.
//
// This is a visible-surface guard, not a sandbox: code that builds a variable
// name at runtime (`python3 -c`, `sh -c`, `eval`), a tool outside the hooked
// shell tools, and a same-uid program that talks to its own fake responder stay
// outside the observation boundary. The refusal message names the variable
// class and never echoes a value or token.


// Sub-agent prohibition: the orchestrator owns issue creation and binding.
const PHASEGENT_ISSUE_WRITE = /\bissue\s+(create|bind)\b/;
// `issue create` names its session through `--session`; `issue bind` takes no
// session flag, so only a create segment gets one injected.
const PHASEGENT_ISSUE_CREATE = /\bissue\s+create\b/;
// `issue close` names its closer through `--worktree-session`: the parser
// rejects `--session` there with `unknown option '--session'` (exit 2,
// src/command/issue.rs), so the segment gets the flag the CLI parses.
const PHASEGENT_ISSUE_CLOSE = /\bissue\s+close\b/;
const SESSION_FLAG = /(^|\s)--session(\s|=)/;
const WORKTREE_SESSION_FLAG = /(^|\s)--worktree-session(\s|=)/;

// Host-driven managed marker, set by the OpenCode shell tool.
const HOST_SESSION_ENV = "OPENCODE_SESSION_ID";

// Every environment name whose visible mutation can change identity or
// transport. The legacy role variable is included even though it grants no
// identity: setting it must not make a managed invocation look ordinary.
const MANAGED_ENV_NAMES = Object.freeze([
  MANAGED_ROLE_ENV,
  MANAGED_SESSION_ENV,
  HOST_SESSION_ENV,
  BROKER_ADDR_ENV,
  BROKER_TOKEN_ENV,
]);

const MANAGED_ENV_SET = new Set(MANAGED_ENV_NAMES);
const ENV_ASSIGNMENT_WORD = /^([A-Za-z_][A-Za-z0-9_]*)\+?=/;
const SHELL_NAME_WORD = /^[A-Za-z_][A-Za-z0-9_]*/;
const PARAMETER_EXPANSION = /^\$(?:\{)?([A-Za-z_][A-Za-z0-9_]*)/;
const ENV_CLEAR = new Set(["-i", "--ignore-environment", "--null"]);
const ENV_UNSET = new Set(["-u", "--unset"]);
const ENV_STRING = new Set(["-S", "--split-string"]);
const COMMAND_KEYWORDS = new Set(["if", "then", "else", "elif", "while", "until", "do", "!", "{", "time"]);

// The session-bearing flag of a segment: `issue create` carries `--session`,
// `issue close` carries `--worktree-session`; every other segment stays
// untouched (`issue bind` takes no session flag at all).
function sessionFlagFor(tail) {
  if (PHASEGENT_ISSUE_CREATE.test(tail)) return { name: "--session", present: SESSION_FLAG };
  if (PHASEGENT_ISSUE_CLOSE.test(tail)) {
    return { name: "--worktree-session", present: WORKTREE_SESSION_FLAG };
  }
  return null;
}

const SUBAGENT_REFUSAL =
  "echo \"phasegent: sub-agent sessions cannot run 'issue create|bind'; ask the orchestrator\" >&2; false";

// Refusal shape shared with the sub-agent guard: print one bounded message to
// stderr and fail, so no mutated command reaches the shell.
const MANAGED_ENV_REFUSAL =
  "echo \"phasegent: refusing this command because it assigns, exports, unsets, or clears a managed phasegent identity/transport environment variable; re-run without modifying those variables\" >&2; false";

function isRedirectionWord(word) {
  return /^\d*(?:>>?|<<?)/.test(word) || /^&>>?/.test(word);
}

// A redirection whose target is a separate word. `2>&1`, `>file`, and
// `<<EOF` carry their target in the same word; the separated forms need the
// operand consumed so the next word is treated as the command, not as an
// ordinary command name.
function redirectionNeedsOperand(word) {
  return /^\d*(?:>>?|<<<?-?|<>|>\|)$/.test(word) || word === "&>" || word === "&>>";
}

function skipRedirection(words, index) {
  if (redirectionNeedsOperand(words[index].value)) {
    return index + 1 < words.length ? index + 2 : -1;
  }
  return index + 1;
}

// `timeout` option tail: returns the index of its command word, or -1 for an
// unsupported/ambiguous shape (which the guard refuses).
function skipTimeout(words, start) {
  let durationSeen = false;
  for (let index = start; index < words.length; index += 1) {
    const word = words[index].value;
    if (word === "--") return durationSeen ? index + 1 : -1;
    if (word === "-s" || word === "--signal" || word === "-k" || word === "--kill-after") {
      index += 1;
      continue;
    }
    if (
      word.startsWith("--signal=") ||
      word.startsWith("--kill-after=") ||
      word === "--preserve-status" ||
      word === "--foreground" ||
      word === "-v" ||
      word === "--verbose"
    ) {
      continue;
    }
    if (word.startsWith("-")) return -1;
    if (!durationSeen) {
      durationSeen = true;
      continue;
    }
    return index;
  }
  return -1;
}

// One destination matcher shared by every mutating operation. Bash treats a
// base name, `NAME`, an indexed destination `NAME[index]`, and an assignment
// `NAME=value`/`NAME[index]=value` as the same variable. The matcher
// normalises those shapes to the base name so `unset VAR[0]` cannot slip past
// an exact-name check.
//
// A destination that looks like a managed name but cannot be conservatively
// resolved (`VAR[` with no closing bracket, `$VAR`/`${VAR}` parameter
// expansion) is reported as unresolved and the caller refuses. Ordinary data
// (`echo`, `printf` format strings, `read -p` prompts, heredoc bodies) never
// reaches this matcher because only assignment/mutator operand positions are
// inspected.
function destinationBase(word) {
  if (typeof word !== "string" || word.length === 0) return null;
  const nameMatch = SHELL_NAME_WORD.exec(word);
  if (!nameMatch) {
    const expansion = PARAMETER_EXPANSION.exec(word);
    return expansion ? { unresolved: true, candidate: expansion[1] } : null;
  }
  const base = nameMatch[0];
  const rest = word.slice(base.length);
  if (rest === "") return { base, assignment: false };
  if (rest.startsWith("=") || rest.startsWith("+=")) {
    return { base, assignment: true };
  }
  if (rest.startsWith("[")) {
    const close = rest.indexOf("]");
    if (close > 0) {
      const after = rest.slice(close + 1);
      if (after === "") return { base, assignment: false };
      if (after.startsWith("=") || after.startsWith("+=")) {
        return { base, assignment: true };
      }
    }
  }
  return { unresolved: true, candidate: base };
}

// A managed destination in any of the accepted shapes, or "unresolved" for a
// managed-looking shape the matcher cannot normalise.
function destinationMutation(word, names) {
  const destination = destinationBase(word);
  if (!destination) return null;
  if (destination.unresolved) {
    return names.has(destination.candidate) ? "unresolved" : null;
  }
  return names.has(destination.base) ? destination.base : null;
}

// Command-position assignment only: `NAME=value`, `NAME+=value`,
// `NAME[index]=value`, never a bare command word.
function assignmentMutation(word, names) {
  const destination = destinationBase(word);
  if (!destination) return null;
  if (destination.unresolved) {
    return names.has(destination.candidate) ? "unresolved" : null;
  }
  if (!destination.assignment) return null;
  return names.has(destination.base) ? destination.base : null;
}

// `export`/`unset`/`declare` style operands: any managed bare name, indexed
// destination, or assignment among the remaining words is a mutation.
function scanNames(words, start, names) {
  for (let index = start; index < words.length; index += 1) {
    const word = words[index].value;
    if (word === "--" || word.startsWith("-")) continue;
    const name = destinationMutation(word, names);
    if (name) return name;
  }
  return null;
}

// `read` assigns every operand name; `-a NAME` assigns the array. Option
// operands (prompt, delimiter, timeout) are skipped so a prompt string that
// looks like a variable name is not a false positive.
function scanRead(words, start, names) {
  let operand = false;
  for (let index = start + 1; index < words.length; index += 1) {
    const word = words[index].value;
    if (operand) {
      const name = destinationMutation(word, names);
      if (name) return name;
      continue;
    }
    if (word === "--") {
      operand = true;
      continue;
    }
    if (word.startsWith("--")) {
      if (word.startsWith("--array=")) {
        const name = destinationMutation(word.slice("--array=".length), names);
        if (name) return name;
      } else if (word === "--array") {
        const name = words[index + 1] && words[index + 1].value;
        const mutation = name && destinationMutation(name, names);
        if (mutation) return mutation;
        index += 1;
      } else if (
        ["--delimiter", "--nchars", "--prompt", "--timeout", "--delim"].includes(word)
      ) {
        index += 1;
      }
      continue;
    }
    if (word.startsWith("-") && word.length > 1) {
      const option = word[1];
      if ("dnNptu".includes(option)) {
        if (word.length === 2) index += 1;
      } else if (option === "a") {
        const name = word.length > 2 ? word.slice(2) : words[index + 1] && words[index + 1].value;
        const mutation = name && destinationMutation(name, names);
        if (mutation) return mutation;
        if (word.length === 2) index += 1;
      }
      continue;
    }
    const name = destinationMutation(word, names);
    if (name) return name;
  }
  return null;
}

// `printf -v NAME` and `mapfile`/`readarray NAME` assign a named shell
// variable. Only the assignment name is inspected; formatting text is data.
function scanPrintf(words, start, names) {
  for (let index = start + 1; index < words.length; index += 1) {
    const word = words[index].value;
    if (word === "--") break;
    if (word === "-v") {
      const name = words[index + 1] && words[index + 1].value;
      const mutation = name && destinationMutation(name, names);
      if (mutation) return mutation;
      index += 1;
    } else if (word.startsWith("-v") && word.length > 2) {
      const mutation = destinationMutation(word.slice(2), names);
      if (mutation) return mutation;
    }
  }
  return null;
}

function scanArrayAssignment(words, start, names) {
  for (let index = start + 1; index < words.length; index += 1) {
    const word = words[index].value;
    if (word === "--") {
      const name = words[index + 1] && words[index + 1].value;
      return name ? destinationMutation(name, names) : null;
    }
    if (word.startsWith("-")) {
      if (/^-[nOscCu]$/.test(word)) index += 1;
      continue;
    }
    return destinationMutation(word, names);
  }
  return null;
}

function scanGetopts(words, start, names) {
  const operands = [];
  for (let index = start + 1; index < words.length; index += 1) {
    const word = words[index].value;
    if (word.startsWith("-")) continue;
    operands.push(word);
    if (operands.length === 2) break;
  }
  return operands[1] ? destinationMutation(operands[1], names) : null;
}

// Direct shell builtins that can assign or remove a named variable from
// visible syntax. `builtin NAME ...` runs the same builtin, so it is handled
// by the same dispatch. Unknown shapes are refused by the caller.
const MUTATING_BUILTINS = new Set([
  "export",
  "declare",
  "typeset",
  "local",
  "readonly",
  "unset",
  "read",
  "printf",
  "mapfile",
  "readarray",
  "getopts",
]);

function scanMutatingBuiltin(words, start, names) {
  const name = words[start] && words[start].value;
  switch (name) {
    case "read":
      return scanRead(words, start, names);
    case "printf":
      return scanPrintf(words, start, names);
    case "mapfile":
    case "readarray":
      return scanArrayAssignment(words, start, names);
    case "getopts":
      return scanGetopts(words, start, names);
    default:
      return scanNames(words, start + 1, names);
  }
}


// `env` wrapper: clear, unset, inline assignment, or split-string recursion.
function scanEnv(words, start, names, depth) {
  for (let index = start; index < words.length; index += 1) {
    const word = words[index].value;
    if (ENV_CLEAR.has(word)) return { found: "clear", next: index };
    if (ENV_UNSET.has(word)) {
      const operand = words[index + 1] && words[index + 1].value;
      const mutation = operand && destinationMutation(operand, names);
      if (mutation) return { found: mutation, next: index };
      index += 1;
      continue;
    }
    if (word.startsWith("--unset=")) {
      const mutation = destinationMutation(word.slice("--unset=".length), names);
      if (mutation) return { found: mutation, next: index };
      continue;
    }
    if (ENV_STRING.has(word)) {
      const operand = words[index + 1] && words[index + 1].value;
      if (operand && depth < 4 && managedMutationInText(operand, names, depth + 1)) {
        return { found: "split-string", next: index };
      }
      index += 1;
      continue;
    }
    if (word === "--") return { found: null, next: index + 1 };
    const assignment = assignmentMutation(word, names);
    if (assignment) return { found: assignment, next: index };
    const destination = destinationBase(word);
    if (destination && destination.unresolved && names.has(destination.candidate)) {
      return { found: "unresolved", next: index };
    }
    if (destination && destination.assignment) {
      index += 1;
      continue;
    }
    if (word.startsWith("-")) return { found: null, next: -1 };
    // The command word: `env` ends here, and later words are its arguments.
    return { found: null, next: index };
  }
  // No command after `env`: printing the environment is not a mutation.
  return { found: null, next: words.length };
}

// Command-position walk of one segment. Assignments are only recognised where
// a simple command starts (after keywords, redirections, transparent wrappers,
// and leading assignments), so quoted arguments such as
// `--body "PHASEGENT_ROLE=x"` stay ordinary data.
function mutationInWords(words, names, depth) {
  let index = 0;
  while (index < words.length) {
    const word = words[index].value;
    if (COMMAND_KEYWORDS.has(word)) {
      index += 1;
      continue;
    }
    if (isRedirectionWord(word)) {
      const next = skipRedirection(words, index);
      if (next < 0) return "unresolved";
      index = next;
      continue;
    }
    if (word === "timeout") {
      index = skipTimeout(words, index + 1);
      if (index < 0) return "unresolved";
      continue;
    }
    if (word === "command") {
      const next = words[index + 1] && words[index + 1].value;
      if (next === "-v" || next === "-V") return null;
      index += 1;
      if (index >= words.length) return null;
      if (words[index].value.startsWith("-")) return "unresolved";
      continue;
    }
    if (word === "builtin") {
      const next = words[index + 1] && words[index + 1].value;
      if (!next) return null;
      if (next.startsWith("-")) return "unresolved";
      if (MUTATING_BUILTINS.has(next)) return scanMutatingBuiltin(words, index + 1, names);
      return null;
    }
    if (word === "env") {
      const result = scanEnv(words, index + 1, names, depth);
      if (result.found) return result.found;
      if (result.next < 0) return "unresolved";
      index = result.next;
      continue;
    }
    const assignment = assignmentMutation(word, names);
    if (assignment) return assignment;
    const destination = destinationBase(word);
    if (destination && destination.unresolved && names.has(destination.candidate)) {
      return "unresolved";
    }
    if (destination && destination.assignment) {
      index += 1;
      continue;
    }
    if (MUTATING_BUILTINS.has(word)) {
      return scanMutatingBuiltin(words, index, names);
    }
    // The ordinary command word: later words are its arguments.
    return null;
  }
  return null;
}

// Whether the whole command visibly mutates any managed variable. Quoted runs
// and heredoc data are not syntax; an unterminated quote is unresolvable and
// therefore refused.
function managedMutationInText(command, names, depth) {
  if (depth > 4) return true;
  if (!maskQuoted(command).balanced) return true;
  const heredoc = scanHeredocRanges(command);
  const opaque = (position) =>
    heredoc.some((range) => position >= range.start && position < range.end);
  for (const segment of shellSegments(command)) {
    const words = shellWords(segment.text).filter(
      (word) => !opaque(segment.start + word.start),
    );
    if (mutationInWords(words, names, depth)) return true;
  }
  return false;
}

// Whether a segment uses a transparent wrapper whose option shape cannot be
// resolved. Such a wrapper is refused (it may execute the CLI), except for the
// `command -v`/`-V` lookup shapes which execute nothing.
function hasUnresolvedWrapper(command) {
  for (const segment of shellSegments(command)) {
    const words = shellWords(segment.text);
    let index = 0;
    while (index < words.length) {
      const word = words[index].value;
      if (COMMAND_KEYWORDS.has(word)) {
        index += 1;
        continue;
      }
      if (isRedirectionWord(word)) {
        const next = skipRedirection(words, index);
        if (next < 0) return true;
        index = next;
        continue;
      }
      if (ENV_ASSIGNMENT_WORD.test(word)) {
        index += 1;
        continue;
      }
      if (word === "timeout") {
        index = skipTimeout(words, index + 1);
        if (index < 0) return true;
        continue;
      }
      if (word === "command") {
        const next = words[index + 1] && words[index + 1].value;
        if (next === "-v" || next === "-V") break;
        if (next && next.startsWith("-")) return true;
        index += 1;
        continue;
      }
      if (word === "env") {
        const result = scanEnv(words, index + 1, new Set(), 0);
        if (result.next < 0) return true;
        index = result.next;
        continue;
      }
      break;
    }
  }
  return false;
}

function rewritePhasegentCommand(command, sessionId, event, options) {
  if (typeof command !== "string" || !command.includes("phasegent")) return command;
  const subagent = isSubagentSession(event);
  const windows =
    options && typeof options.windows === "boolean" ? options.windows : isWindowsHost();
  const source = command;
  const entries = shellSegments(source)
    .map((segment) => ({ segment, invocation: phasegentInvocation(segment) }))
    .filter((entry) => entry.invocation);
  if (entries.length === 0) {
    if (managedMutationInText(source, MANAGED_ENV_SET, 0)) {
      warn("phasegent: refused a command that mutates managed identity environment variables");
      return MANAGED_ENV_REFUSAL;
    }
    if (hasUnresolvedWrapper(source)) {
      warn("phasegent: refused a command with an unresolved wrapper around phasegent");
      return MANAGED_ENV_REFUSAL;
    }
    return source;
  }
  if (subagent && entries.some(({ invocation }) => PHASEGENT_ISSUE_WRITE.test(invocation.tail))) {
    warn("phasegent: sub-agent session refused 'issue create|bind' (orchestrator-only)");
    return SUBAGENT_REFUSAL;
  }
  if (managedMutationInText(source, MANAGED_ENV_SET, 0)) {
    warn("phasegent: refused a command that mutates managed identity environment variables");
    return MANAGED_ENV_REFUSAL;
  }
  let result = source;
  // Insert from the last invocation backwards so earlier offsets stay valid.
  for (let index = entries.length - 1; index >= 0; index -= 1) {
    const { invocation } = entries[index];
    // An unterminated quote leaves no injection point that is provably outside
    // the value: that segment stays byte-for-byte.
    if (!invocation.balanced) continue;
    // A wrapped invocation is a POSIX transparent-wrapper shape; on Windows the
    // segment has no supported interpretation, so it stays untouched rather
    // than nesting a PowerShell scope inside a foreign wrapper (issue #917 P1).
    if (windows && invocation.wrapped) continue;
    const tailFlags = [];
    const sessionFlag = sessionId ? sessionFlagFor(invocation.tail) : null;
    if (sessionFlag && !sessionFlag.present.test(invocation.tail)) {
      tailFlags.push(`${sessionFlag.name} ${sessionId}`);
    }
    const tail = tailFlags.length > 0 ? ` ${tailFlags.join(" ")}` : "";
    if (tail) {
      result = `${result.slice(0, invocation.segmentEnd)}${tail}${result.slice(invocation.segmentEnd)}`;
    }
  }
  return result;
}

// The agent role the host reported for the current tool call. The role is a
// host fact, never a command-text claim, and it is only used for the
// sub-agent refusal.
function sessionAgentRole(event) {
  return agentRole(event);
}

// assets/opencode/src/session.js
// Acquired-worktree registry and session placement (issue #440; parent
// inheritance issue #567; prompt-time placement issue 37; exact session
// ownership issue 919 P1).
//
// `ctx.session.move` relocates a session, and the host's session info
// (`ctx.session.get`) reports a Task-spawned child's `parentID` plus the
// session's own `location.directory`. The registry is an exact per-session map:
// a session's worktree is the one recorded under its own id, and there is no
// cross-session fallback. An unknown session therefore has no worktree — it can
// never be handed another session's directory — and a child inherits only its
// parent's directory (the parent's registered target, or the directory the host
// reports for the parent), never the most recently remembered worktree.
//
// The host is the only authority on where a session *is*: a fresh own-session
// read decides whether a known placement still holds, and a decided move whose
// source cannot be verified fails closed rather than running the turn in an
// unverified directory. Every placement is decided once per session from the
// session prompt hook, so no tool call is ever cancelled to move a session.


// Every error the placement itself raises starts with this prefix (issue 37):
// `discovery.ensureSessionWorktree` rethrows exactly these past its guarded
// probe, so a move the host cannot perform fails the prompt instead of running
// the turn in the old checkout, while an ordinary discovery failure still
// degrades to the current checkout.
const PLACEMENT_ERROR_PREFIX = "phasegent: session placement";

const sessionWorktrees = new Map();
// The directory a session occupied when its registered target was decided.
//
// The host reports where a session *is*, never whether an accepted move has
// landed yet, so the registry keeps this origin to tell the two apart: a
// target whose move is still pending keeps the session at its origin, while a
// session the host reports anywhere else was relocated. It comes from
// authoritative host metadata only, never from the plugin's context or from the
// cached session record.
const placementOrigins = new Map();
// Targets the host moved a session out of.
//
// A relocation the host made is authoritative and stays authoritative for that
// session, so a later lease rediscovery must not hand the same target back.
// The record is session-local and target-specific: another target, a new issue
// or another worktree is never blocked.
const abandonedTargets = new Map();
// The placement attempt a session runs, the target it moves to, and the host
// move it dispatched. A superseded attempt keeps its dispatch promise, so the
// attempt that replaces it waits for the earlier host move instead of
// overtaking it, while the superseded attempt itself skips the host move it
// never dispatched and publishes no placement state.
const moveAttempts = new Map();
const placedSessions = new Set();
// Sessions whose placement the host has actually confirmed at the registered
// directory. `placedSessions` records an *admitted* placement (the runner
// applies it at the next step boundary); `confirmedSessions` records that a
// fresh host read agreed, which is the only state that lets a reconciliation
// treat a differing host answer as an external relocation rather than a move
// that has not landed yet.
const confirmedSessions = new Set();
const sessionInfo = new Map();
const closedIssues = new Set();

// `sessionPlaced` reports a *settled* placement: the session already sat in the
// worktree, or its move was admitted and the runner applies it at the next step
// boundary. Either way the decision is made, so later prompts never re-move it.
function sessionPlaced(sessionId) {
  return sessionId !== undefined && sessionId !== null && placedSessions.has(String(sessionId));
}

// Records a placement the host already confirms (the session's reported
// directory is the worktree) so no move is issued for it.
function markPlaced(sessionId) {
  if (sessionId === undefined || sessionId === null) return;
  placedSessions.add(String(sessionId));
}

// Records that a fresh host read agreed the session is at its registered
// directory, so a later differing answer is a relocation and not a lagging host.
function markConfirmed(sessionId) {
  if (sessionId === undefined || sessionId === null) return;
  confirmedSessions.add(String(sessionId));
}

// True when a fresh host read agreed the session sits at its registered
// directory. Only a confirmation ends the tolerance for a pending target.
function hostConfirmed(sessionId) {
  return sessionId !== undefined && sessionId !== null && confirmedSessions.has(String(sessionId));
}

// The attempt this session runs, or `null` when no attempt is current: none
// was started, or the one that ran was superseded by another target.
function currentAttempt(key) {
  const record = moveAttempts.get(key);
  return record && record.attempt ? record.attempt : null;
}

// Retires the attempt this session runs without dropping the host move it
// already dispatched: the next attempt waits for that move instead of
// overtaking it.
function supersedeAttempt(key) {
  const record = moveAttempts.get(key);
  if (record) record.attempt = null;
}

// A refused acquisition is remembered per issue: the session stays in the
// main checkout, and the next prompt must not repeat the lease probe or
// the warning.
function issueKnownClosed(issueId) {
  return closedIssues.has(String(issueId));
}

function rememberClosedIssue(issueId) {
  closedIssues.add(String(issueId));
}

// Exact per-session registration. A miss (unknown or absent session) records
// nothing and never borrows another session's directory.
//
// `origin` is the directory the session occupied when this target was decided.
// It is the evidence that keeps a pending target valid while the host still
// reports the origin, so a later relocation cannot be mistaken for a move that
// has not landed yet.
//
// The origin and the placement markers belong to one target. Registering the
// same target again keeps them, so a repeated admission cannot destroy the
// evidence of a move that is still pending; registering a different target
// drops them, so markers of the previous target never decide the placement of
// the new one.
function rememberWorktree(sessionId, directory, origin) {
  if (typeof directory !== "string" || directory.length === 0) return;
  if (sessionId === undefined || sessionId === null) return;
  const key = String(sessionId);
  const previous = sessionWorktrees.get(key);
  if (previous !== undefined && previous !== directory) {
    placementOrigins.delete(key);
    placedSessions.delete(key);
    confirmedSessions.delete(key);
    // The attempt in flight belongs to the previous target: it must not
    // suppress the new move and the new target must not join it. Its dispatched
    // host move stays recorded, so the new move waits for it.
    supersedeAttempt(key);
  }
  sessionWorktrees.set(key, directory);
  if (typeof origin === "string" && origin.length > 0) placementOrigins.set(key, origin);
}

// The origin recorded for a session's registered target, or `null` when none
// was proven.
function placementOrigin(sessionId) {
  if (sessionId === undefined || sessionId === null) return null;
  const known = placementOrigins.get(String(sessionId));
  return known === undefined ? null : known;
}

// Remembers that the host moved this session out of `directory`. The record
// survives the target it belonged to, so a later lease rediscovery cannot
// resurrect a target the session was relocated away from.
function markTargetAbandoned(sessionId, directory) {
  if (sessionId === undefined || sessionId === null) return;
  if (typeof directory !== "string" || directory.length === 0) return;
  const key = String(sessionId);
  let targets = abandonedTargets.get(key);
  if (!targets) {
    targets = new Set();
    abandonedTargets.set(key, targets);
  }
  targets.add(directory);
}

// True when the host moved this session out of `directory`.
function targetAbandoned(sessionId, directory) {
  if (sessionId === undefined || sessionId === null) return false;
  if (typeof directory !== "string" || directory.length === 0) return false;
  const targets = abandonedTargets.get(String(sessionId));
  return targets ? targets.has(directory) : false;
}

// The session's own registered worktree, or `null` when it has none.
function worktreeForSession(sessionId) {
  if (sessionId === undefined || sessionId === null) return null;
  const known = sessionWorktrees.get(String(sessionId));
  return known === undefined ? null : known;
}

function resetWorktrees() {
  sessionWorktrees.clear();
  placementOrigins.clear();
  abandonedTargets.clear();
  moveAttempts.clear();
  placedSessions.clear();
  confirmedSessions.clear();
  sessionInfo.clear();
  closedIssues.clear();
}

// `context.session.get` is the host's session lookup: `parentID` names the
// session that spawned this one, and `location.directory` is where the session
// runs. The result is cached per session because the prompt hook must not add a
// host call to every turn; a failed lookup stays uncached so a later prompt can
// still inherit.
async function fetchSessionInfo(context, sessionId) {
  const get = context && context.session && context.session.get;
  if (typeof get !== "function") return null;
  let info = null;
  try {
    const result = await get({ sessionID: sessionId });
    if (result && typeof result === "object") {
      const parentID = typeof result.parentID === "string" ? result.parentID : "";
      const directory =
        result.location && typeof result.location.directory === "string"
          ? result.location.directory
          : "";
      info = { parentID: parentID || null, directory: directory || null };
    }
  } catch (_) {
    info = null;
  }
  return info;
}

function hostSessionLookupAvailable(context) {
  const get = context && context.session && context.session.get;
  return typeof get === "function";
}

async function readSessionInfo(context, sessionId) {
  if (sessionId === undefined || sessionId === null) return null;
  const key = String(sessionId);
  if (sessionInfo.has(key)) return sessionInfo.get(key);
  if (!hostSessionLookupAvailable(context)) {
    sessionInfo.set(key, null);
    return null;
  }
  const info = await fetchSessionInfo(context, sessionId);
  if (info) sessionInfo.set(key, info);
  return info;
}

// Issue 747 P2: the host is the only authority on where a session runs, so a
// reconciliation is never answered from the cache above — the cached record
// exists to keep an ordinary inheritance lookup off the host, and answering
// "is my placement still valid?" from it is exactly the stale answer that would
// send a session back into a worktree `issue close` already removed. A usable
// answer refreshes the cache so the next ordinary lookup is current too.
async function readAuthoritativeDirectory(context, sessionId) {
  if (sessionId === undefined || sessionId === null) return null;
  const info = await fetchSessionInfo(context, sessionId);
  if (info) sessionInfo.set(String(sessionId), info);
  return info ? info.directory : null;
}

// Drops every cached reference to a worktree the host no longer associates
// with this session: its registered target, the origin that justified it, the
// settled and confirmed markers, an in-flight move, and the cached host record
// that produced the stale answer. The state is cleared together, so no
// obsolete target can outlive the evidence that supported it. The record of a
// target the host moved the session out of survives: it is the evidence that
// keeps a later rediscovery from handing that target back.
function forgetSessionWorktree(sessionId, _directory) {
  if (sessionId === undefined || sessionId === null) return;
  const key = String(sessionId);
  sessionWorktrees.delete(key);
  placementOrigins.delete(key);
  sessionInfo.delete(key);
  placedSessions.delete(key);
  confirmedSessions.delete(key);
  supersedeAttempt(key);
}

// The parent's directory is the destination a child follows.
//
// The host is the only authority on where the parent runs, so the parent is
// read fresh on every inheritance: the cached session record can name a
// directory the parent was moved out of long ago. A registered parent target is
// then reconciled against that fresh answer:
//
//   * the host reports the target: the parent sits in it, the child follows;
//   * the host reports the recorded origin and the target was never confirmed:
//     the accepted move has not landed yet, so the child follows the pending
//     target rather than the lagging host answer;
//   * the host reports any other directory — a third one, or the origin of an
//     already confirmed target: the parent was relocated, so its stale target
//     is dropped and the child follows the host.
//
// A parent the host cannot describe gives the child nothing at all: no cached
// directory, no issue-lease discovery, and never a stale target.
async function inheritedWorktree(context, parentId, readDirectory) {
  if (parentId === undefined || parentId === null) return null;
  const key = String(parentId);
  const registered = sessionWorktrees.get(key);
  const read = readDirectory || readAuthoritativeDirectory;
  const directory = await read(context, parentId);
  if (!directory) return null;
  if (!registered) return directory;
  if (directory === registered) {
    markConfirmed(parentId);
    return registered;
  }
  const origin = placementOrigin(parentId);
  if (origin && directory === origin && !hostConfirmed(parentId)) {
    // The parent's accepted move has not landed yet: the child follows the
    // pending target instead of the lagging host answer.
    return registered;
  }
  markTargetAbandoned(parentId, registered);
  forgetSessionWorktree(parentId, registered);
  placementDiagnostic("skip", { session: key, reason: "reconciled-elsewhere" });
  return directory;
}

// `context.session.move` hands an active runner the placement at its next step
// boundary (packages/core/src/session/move.ts, runner/llm.ts). Placement runs
// from the session prompt hook (issue 37), which is admitted before the runner
// reaches any tool call, so the move lands before the first tool call of the
// turn: there is no in-flight call to protect and nothing to cancel. The move
// itself still fails closed — a host that cannot report the session's current
// directory, or cannot move it, raises a prefixed error that fails the prompt,
// so no turn is ever run unplaced. `moveAttempts` joins concurrent prompts onto
// one placement, and a failure clears with the attempt so the next prompt
// retries.
//
// Issue 919 P1: the *fresh own-session* directory the host reports — not
// `context.location` and not the `currentDirectory` compatibility hint — is what
// decides whether a move is needed. When the host cannot report it, a decided
// placement is never guessed from plugin context.
async function moveSessionToWorktree(context, sessionId, directory, _currentDirectory) {
  if (typeof directory !== "string" || directory.length === 0) return;
  if (sessionId === undefined || sessionId === null) return;
  const key = String(sessionId);
  if (placedSessions.has(key)) return;
  if (!context) {
    throw new Error(
      `${PLACEMENT_ERROR_PREFIX} unavailable for '${key}': no host context, so '${key}' ` +
        `cannot enter ${directory}`,
    );
  }
  const pending = currentAttempt(key);
  if (pending) {
    await pending;
    return;
  }
  const record = moveAttempts.get(key);
  const earlier = record ? record.dispatched : null;
  let attempt = null;
  attempt = (async () => {
    if (earlier) {
      // An earlier host move may still be in flight. The dispatched moves are
      // serialized, so this request cannot overtake it and be overwritten by
      // its completion. The earlier attempt's own failure is its own.
      try {
        await earlier;
      } catch (_) {
        // The superseded attempt reported its own failure.
      }
      // The attempt may have been superseded while it waited: it must neither
      // read for a placement nor move the session.
      if (currentAttempt(key) !== attempt) return null;
    }
    // The source must be the host's fresh, authoritative answer for this very
    // session. A cached value or the plugin's own location could be stale, and
    // guessing could send the turn into a directory that is about to vanish.
    // The read follows the wait above, so the answer reflects the earlier host
    // move and cannot be invalidated by it.
    const located = await readAuthoritativeDirectory(context, sessionId);
    // The read can outlive the decision: the session may have moved on to
    // another target while it was in flight. A superseded attempt must
    // neither move the session nor publish placement state, so it checks that
    // it is still the attempt this session runs.
    if (currentAttempt(key) !== attempt) return null;
    if (typeof located !== "string" || located.length === 0) {
      placementDiagnostic("unverified", {
        session: key,
        to: directory,
        reason: "no-authoritative-directory",
      });
      throw new Error(
        `${PLACEMENT_ERROR_PREFIX} unverified for '${key}': the host could not report the ` +
          `current directory, so '${key}' cannot be moved to ${directory}`,
      );
    }
    if (located === directory) {
      placedSessions.add(key); // the session already sits in the worktree
      markConfirmed(key);
      placementDiagnostic("suppressed", {
        session: key,
        from: located,
        to: directory,
        reason: "already-in-target",
      });
      return directory;
    }
    // The fresh read is the session's origin: the directory it occupies before
    // this move. Recording it here gives the next prompt the evidence that
    // separates a move which has not landed yet from a session that was
    // relocated elsewhere, and it is written before the move is requested so a
    // rejected move still leaves the origin known.
    if (!placementOrigins.has(key)) placementOrigins.set(key, located);
    const move = context && context.session && context.session.move;
    if (typeof move !== "function") {
      throw new Error(
        `${PLACEMENT_ERROR_PREFIX} unavailable for '${key}': the host exposes no session.move, ` +
          `so '${key}' cannot enter ${directory} and stays in ${located}`,
      );
    }
    placementDiagnostic("request", { session: key, from: located, to: directory });
    try {
      const dispatched = move({ sessionID: sessionId, directory });
      const running = moveAttempts.get(key);
      if (running) running.dispatched = dispatched;
      await dispatched;
    } catch (error) {
      placementDiagnostic("rejected", {
        session: key,
        to: directory,
        reason: "move-rejected",
      });
      throw new Error(
        `${PLACEMENT_ERROR_PREFIX} failed for '${key}': moving to ${directory} rejected ` +
          `(${errorText(error)}); the next prompt retries`,
      );
    }
    // The host may have taken long enough for the attempt to be superseded, so
    // the placement state is published only while the attempt still runs.
    if (currentAttempt(key) === attempt) placedSessions.add(key);
    // The host *accepted* the move; that is not proof it relocated, so this is
    // deliberately not labelled a confirmation.
    placementDiagnostic("accepted", { session: key, from: located, to: directory });
    return directory;
  })();
  moveAttempts.set(key, { target: directory, attempt, dispatched: earlier || null });
  try {
    await attempt;
  } finally {
    const running = moveAttempts.get(key);
    if (running && running.attempt === attempt) moveAttempts.delete(key);
  }
}

// Exact-session reuse: a session's own registered worktree, or nothing. Never a
// cross-session fallback.
async function reuseRememberedWorktree(context, sessionId) {
  const known = worktreeForSession(sessionId);
  if (!known) return null;
  await moveSessionToWorktree(context, sessionId, known);
  return known;
}

// assets/opencode/src/session-reconcile.js
// Reconciling the worktree registry against the host.
//
// A lease records where a session *was*, and this registry recorded where the
// plugin put it. Neither survives an authoritative move: `issue close` returns
// the closing session to the repository's main checkout through the OpenCode
// API before it removes the worktree, and the directory a cached entry names can
// be gone by the time the next prompt arrives. A move made out of band — the
// OpenCode API, or another operator — is invisible to the registry in exactly
// the same way. So the host is read fresh and the answer decides:
//
//   * the host reports the registered target: the placement is settled and the
//     host confirmed it;
//   * the host reports the recorded origin while the target was never
//     confirmed: the accepted move has not landed yet, so the target stays
//     pending. Only a confirmation ends that tolerance, never the acceptance
//     of the move itself;
//   * the host reports any other directory — a third one, or the origin of an
//     already confirmed target: the session was relocated, so the stale target
//     is dropped, remembered as abandoned, and the host wins;
//   * the host cannot be read: a settled session drops its target, because the
//     directory may already be gone, and an unsettled one keeps it so the move
//     itself fails closed instead of the turn running unplaced.
//
// A registered-but-unsettled session is reconciled too: a target whose settled
// markers are missing used to win unconditionally, so the next prompt moved a
// session the host had already relocated back into the stale directory.


// True when the registered target for `sessionId` may still be used.
//
// `readDirectory` is the injection seam; it defaults to the uncached host read
// and a caller must not substitute a cached reader, because answering this
// question from a cache is the failure this module exists to prevent.
async function reconcileSessionLocation(context, sessionId, readDirectory) {
  const key = sessionId === undefined || sessionId === null ? null : String(sessionId);
  const registered = key === null ? undefined : sessionWorktrees.get(key);
  // A session without a registered target has nothing to reconcile.
  if (!registered) return true;
  const read = readDirectory || readAuthoritativeDirectory;
  const directory = await read(context, sessionId);
  if (!directory) {
    if (sessionPlaced(sessionId)) {
      forgetSessionWorktree(sessionId, registered);
      placementDiagnostic("skip", { session: key, reason: "reconciled-elsewhere" });
      return false;
    }
    // An unsettled placement keeps its target, so the move itself fails closed
    // on the unreadable host instead of the turn running unplaced.
    return true;
  }
  if (directory === registered) {
    // The session sits in its target: the placement is settled and the host
    // confirmed it.
    markConfirmed(sessionId);
    return true;
  }
  const origin = placementOrigin(sessionId);
  if (origin && directory === origin && !hostConfirmed(sessionId)) {
    // The accepted move has not landed yet: the target stays pending.
    return true;
  }
  // The session was relocated. Its target is dropped and remembered as
  // abandoned, so a later lease rediscovery cannot hand it back.
  markTargetAbandoned(sessionId, registered);
  forgetSessionWorktree(sessionId, registered);
  placementDiagnostic("skip", { session: key, reason: "reconciled-elsewhere" });
  return false;
}

// assets/opencode/src/discovery.js
// Lazy worktree discovery and the per-session placement decision.
//
// Placement runs from the session prompt hook (issue 37), once per session and
// before the runner reaches any tool call, so a move never has to cancel an
// in-flight invocation. A session with neither a registered nor an inherited
// worktree probes the checkout's issue binding and the issue's leases, and reuses
// a path only when one is already recorded. Creating a worktree is opt-in
// (issue 616): with no reusable lease the session keeps the current checkout and
// is pointed at the explicit `phasegent worktree acquire --isolate` command
// instead. A Task-spawned child follows its parent's directory first and never
// reaches the probes below, so it can neither acquire nor guess one.
//
// Issue 919 P1: the registry is exact per session. There is no cross-session
// fallback, so an unknown session — or a child whose parent cannot be resolved —
// stays where it is instead of being redirected into another session's worktree.
//
// The host is the authority for both an own registered target and an inherited
// one, and it is read fresh for every placement decision. A cached session
// record or the plugin's own context is never placement evidence, so a session
// the host relocated out of band is never moved back to a stale directory, and
// a target it was moved out of is not handed back by a later rediscovery.


// A decided placement must fail closed: only errors raised by the move itself
// (identified by `PLACEMENT_ERROR_PREFIX`) rethrow past the discovery guard, so
// a host move rejection fails the prompt while an ordinary probe failure keeps
// the session in the current checkout.
function isPlacementFailure(error) {
  return error instanceof Error && error.message.startsWith(PLACEMENT_ERROR_PREFIX);
}

async function discoverWorktreeForSession(sessionId, cwd) {
  if (phasegentCallsDisabled()) return null;
  try {
    if (!sessionId) return null;
    const known = worktreeForSession(sessionId);
    if (known) return known;
    const issueId = await readBranchBinding(cwd);
    if (!issueId) return null;
    const leases = await readIssueLeases(issueId, cwd);
    if (!leases) return null;
    const path = pickActiveWorktreePath(leases);
    if (!path) return null;
    // A target the host moved this session out of stays abandoned: the
    // relocation is authoritative and rediscovery must not resurrect it. The
    // origin of the target is recorded from authoritative host metadata by the
    // move that follows this registration, never from the plugin's context.
    if (targetAbandoned(sessionId, path)) return null;
    rememberWorktree(sessionId, path);
    return path;
  } catch (_) {
    return null;
  }
}

// A refused placement is remembered per (session, issue): the session stays in
// the current checkout, so the next prompt must not repeat the same warning.
// A fresh session id (or a new issue binding) warns again, and a lease that
// appears later is still picked up by the reuse probe before this guard.
const refusedPlacements = new Set();

function warnRefusedPlacement(sessionId, issueId) {
  const key = `${sessionId}:${issueId}`;
  if (refusedPlacements.has(key)) return;
  refusedPlacements.add(key);
  warn(
    `phasegent: no worktree was created for issue ${issueId} (isolation is opt-in); ` +
      "staying in the current checkout. Run `phasegent worktree acquire " +
      `--issue ${issueId} --isolate\` for a dedicated worktree.`,
  );
}

// The one placement decision for a session, run from the session prompt hook
// (issue 37): a Task-spawned child follows its parent's directory first, so it
// never reaches the probes below and can neither acquire nor guess a worktree.
// `PHASEGENT_WORKTREE_NO_DISCOVER` keeps the adapter inert beyond the exact
// in-memory registry: no host session lookup, no CLI, no acquire, and no
// auto-move (the current location cannot be verified without a host read). The
// rest is guarded — an ordinary discovery failure keeps the session in the
// current checkout — while a decided placement rethrows out of the `try` so the
// prompt fails instead of running unplaced. `deps` is an internal seam so tests
// can exercise that order without the phasegent CLI.
async function ensureSessionWorktree(context, sessionId, deps) {
  if (!sessionId) return null;
  // `PHASEGENT_WORKTREE_NO_DISCOVER` keeps the adapter inert: the exact
  // in-memory lookup is local, and no host read or auto-move follows,
  // because a move whose current location cannot be verified must never run.
  if (phasegentCallsDisabled()) return worktreeForSession(sessionId);
  // The host, not this registry, decides where a session runs. A settled *and*
  // an unsettled placement are reconciled against a fresh host read before its
  // cached target is trusted, so a relocation the host made is never reversed
  // and a worktree that was already removed is never re-entered. An unsettled
  // session is untouched otherwise, so the ordinary first placement still
  // happens.
  const readDirectory =
    (deps && deps.readAuthoritativeDirectory) || readAuthoritativeDirectory;
  if (!(await reconcileSessionLocation(context, sessionId, readDirectory))) return null;
  const readInfo = (deps && deps.readSessionInfo) || readSessionInfo;
  const discover = (deps && deps.discover) || discoverWorktreeForSession;
  const readBinding = (deps && deps.readBinding) || readBranchBinding;
  const readLeaseHistory = (deps && deps.readLeaseHistory) || readIssueLeaseHistory;
  try {
    // A child inherits before its own registration and before the reuse probe:
    // it takes its parent's current directory or nothing at all, never another
    // session's worktree. The parent's fresh location is the authority, so a
    // child whose parent moved follows it.
    const info = await readInfo(context, sessionId);
    if (info && info.parentID) {
      return await inheritParentWorktree(context, sessionId, info, readDirectory);
    }
    const registered = worktreeForSession(sessionId);
    if (registered) {
      // Move-only placement: a move the host cannot perform fails the prompt.
      await moveSessionToWorktree(context, sessionId, registered);
      return registered;
    }
    // The probes run where the session actually is: the plugin's own context
    // location and the cached session record are not the session's directory and
    // never decide where a session is placed.
    const cwd = await readDirectory(context, sessionId);
    const discovered = await discover(sessionId, cwd);
    if (discovered) {
      if (targetAbandoned(sessionId, discovered)) {
        // The host moved this session out of that target, so the rediscovery
        // must not put it back.
        forgetSessionWorktree(sessionId, discovered);
        return null;
      }
      await moveSessionToWorktree(context, sessionId, discovered);
      return discovered;
    }
    const issueId = await readBinding(cwd);
    if (!issueId) return null;
    if (issueKnownClosed(issueId)) return null;
    if (await issueConverged(issueId, cwd, readLeaseHistory)) {
      warn(`phasegent: issue ${issueId} is closed; refusing to acquire a worktree (staying put)`);
      return null;
    }
    // Automatic creation is opt-in (issue 616): with no reusable lease the
    // session keeps the current checkout instead of being moved into a freshly
    // created worktree, and the explicit isolation command is the opt-in.
    warnRefusedPlacement(sessionId, issueId);
    return null;
  } catch (error) {
    if (isPlacementFailure(error)) throw error;
    warn(`phasegent: worktree discovery failed; reusing original directory (${errorText(error)})`);
    return null;
  }
}

// The local, offline closed marker: `issue close` and `issue sync` converge a
// lease row instead of deleting it, so its "issue closed…" release reason is
// what the adapter reads. Remembering the answer keeps the next prompt off the
// CLI. A binding that cannot be read leaves the decision to the caller.
async function issueConverged(issueId, cwd, readLeaseHistory) {
  if (issueKnownClosed(issueId)) return true;
  if (!issueClosedLocally(await readLeaseHistory(issueId, cwd))) return false;
  rememberClosedIssue(issueId);
  return true;
}

// The parent's registered target is the destination of a move that may still be
// pending at the parent's next step boundary; the directory the host reports for
// the parent is the fallback once that move has landed. A prompt has run no tool
// yet, so the child's move is admitted and the turn continues: it lands before
// the child's first tool call. A parent with no resolvable directory is not an
// error — the child simply stays where it is.
//
// The parent's location comes from the host, never from the cached session
// record, and the parent's own stale target is reconciled before the child
// follows it. The child's target is registered here and its origin comes from
// the authoritative read inside the move below.
async function inheritParentWorktree(context, sessionId, info, readDirectory) {
  const target = await inheritedWorktree(context, info.parentID, readDirectory);
  if (!target) return null;
  // The host moved this child out of that target before: the inherited target
  // must not put the child back into it.
  if (targetAbandoned(sessionId, target)) return null;
  if (info.directory === target) {
    // The cached record suggests the child already sits in the parent's
    // directory. That is a placement decision, so the host confirms it with a
    // fresh read before the child is treated as placed.
    const located = await readDirectory(context, sessionId);
    if (located === target) {
      // The child already occupies the parent's directory. The target and its
      // origin are recorded anyway, so a later external relocation of the child
      // can be reconciled, and the child is placed without being moved.
      rememberWorktree(sessionId, target, located);
      markPlaced(sessionId);
      markConfirmed(sessionId);
      return null;
    }
  }
  rememberWorktree(sessionId, target);
  await moveSessionToWorktree(context, sessionId, target, info.directory);
  return target;
}

// assets/opencode/src/paths.js
// Pure path helpers (issue #440; split by issue #541; placement became
// move-only in issue 623 — the hook no longer rewrites tool arguments for
// placement, these helpers stay exported for the plugin's `redirect` surface
// and keep the v2 tool vocabulary documented).
//
// Only relative values are rewritten; everything absolute (POSIX, Windows drive
// or UNC) is returned verbatim so an explicit escape is never silently
// retargeted and the external_directory check still sees the path the model
// asked for. v2 renamed the file tools' `filePath` to `path` and the shell tool
// from `bash` to `shell` (packages/core/src/tool/plugin/{read,write,edit}.ts,
// tool/shell.ts:22). Shell command rewriting (issue #541) lives in the hook;
// these helpers only retarget filesystem paths.

function isAbsolutePath(value) {
  if (typeof value !== "string" || value.length === 0) return false;
  if (value.startsWith("/")) return true;
  if (/^[A-Za-z]:[\\/]/.test(value)) return true;
  return value.startsWith("\\\\");
}

function redirectPathValue(workdir, value) {
  if (typeof workdir !== "string" || workdir.length === 0) return value;
  if (typeof value !== "string" || value.length === 0) return value;
  if (isAbsolutePath(value)) return value;
  return `${workdir.replace(/[\\/]+$/, "")}/${value.replace(/^[\\/]+/, "")}`;
}

const PATH_ARG_KEYS = {
  read: ["path"],
  write: ["path"],
  edit: ["path"],
  glob: ["path"],
  grep: ["path"],
};

const SEARCH_TOOLS = ["glob", "grep"];
const SHELL_TOOLS = ["shell", "bash"];

function redirectPaths(tool, workdir, args) {
  if (!args || typeof args !== "object") return args;
  if (typeof workdir !== "string" || workdir.length === 0) return args;
  const redirected = { ...args };
  const keys = PATH_ARG_KEYS[tool];
  if (SEARCH_TOOLS.includes(tool)) {
    const current = redirected.path;
    if (typeof current !== "string" || current.length === 0) {
      redirected.path = workdir;
    } else {
      redirected.path = redirectPathValue(workdir, current);
    }
  } else if (keys) {
    for (const key of keys) {
      if (typeof redirected[key] === "string") {
        redirected[key] = redirectPathValue(workdir, redirected[key]);
      }
    }
  }
  if (SHELL_TOOLS.includes(tool)) {
    const current = redirected.workdir;
    if (typeof current === "string" && current.length > 0) {
      redirected.workdir = redirectPathValue(workdir, current);
    } else {
      // Bare shell: the shell would otherwise default to the stale session cwd.
      redirected.workdir = workdir;
    }
  }
  return redirected;
}

// assets/opencode/src/hook.js
// The v2 runtime hooks: placement, and phasegent command rewriting.
//
// `context.session.hook("prompt", event)` receives the same mutable payload
// object for every submitted turn (`{ sessionID, messageID, prompt, metadata,
// delivery }`, core `SessionPrompt.prepare`). It owns the whole placement
// decision (issue 37): the session is registered, inherited, or discovered and
// then moved before the runner reaches any tool call, so the move lands at the
// runner's next step boundary with no in-flight invocation to protect and
// nothing to cancel. A host that cannot move the session still fails the prompt,
// so no turn runs unplaced.
//
// `context.tool.hook("execute.before", event)` receives
// `{ tool, sessionID, agent, messageID, id, input }`; core continues with the
// returned `event.input` and rethrows a hook error before the tool executes
// (packages/core/src/tool.ts:103-111, :271-280). It only rewrites shell
// commands, so phasegent invocations carry their role and session and a
// sub-agent cannot run the orchestrator-only `issue create`/`bind`. It holds no
// placement state and raises no placement error.


function createRedirectHook(bridge) {
  return async function executeBefore(event) {
    if (!event || typeof event.input !== "object") return;
    const command = event.input.command;
    if (!SHELL_TOOLS.includes(event.tool) || typeof command !== "string") return;
    try {
      const rewritten = rewritePhasegentCommand(command, event.sessionID, event);
      if (rewritten !== command) event.input.command = rewritten;
      // L1 managed bridge: after the existing rewrite, store the exact
      // rewritten bytes under a fresh nonce and prepend the inert header.
      // Unknown roles still decorate (marker with no role) so the shell
      // fails closed instead of becoming Operator. Without a bridge (host
      // exposes no shell hook) the rewrite-only path stays as-is.
      if (bridge && typeof bridge.decorate === "function") {
        try {
          const sessionID =
            typeof event.sessionID === "string" ? event.sessionID : null;
          if (sessionID && sessionID.length > 0) {
            const role = agentRole(event);
            const toolCallId = typeof event.id === "string" ? event.id : null;
            const decorated = bridge.decorate(
              event.input.command,
              sessionID,
              role,
              toolCallId,
            );
            if (typeof decorated === "string") event.input.command = decorated;
          }
        } catch (_) {
          // Decoration never breaks the rewrite; a failed decorate keeps the
          // rewritten command so the existing path still applies.
        }
      }
    } catch (_) {
    }
  };
}

// The prompt hook mutates the payload in place: the host keeps the object it
// passed, so the handler only has to read `sessionID`.
function createPromptHook(context, deps) {
  return async function onPrompt(event) {
    if (!event) return;
    await ensureSessionWorktree(context, event.sessionID, deps);
  };
}

// assets/opencode/src/notify.js
// Best-effort question-awaiting-user notification (issue #1026 P1/P2).
//
// The adapter subscribes to the host event stream and tracks each *new* local
// pending question form. A form still unanswered after five minutes invokes the
// existing `phasegent notify send --stdin` CLI once with a structured, bounded
// JSON document on stdin; reply, cancellation, session deletion, disposal, and
// stream loss cancel the pending reminder. It never answers a question, never
// blocks or fails the question tool, and never inspects credentials or local
// databases: delivery is one bounded, argv-only child process that reuses the
// operator's configured channel and inherits the environment unchanged
// (including any role/session markers the ambient caller already carries).
//
// The official v2 subscription is an AsyncIterable (`context.event.subscribe`),
// the payload lives in `event.data.form`, and a question is a `form.created`
// whose `metadata.kind` is `"question"`. Only events whose location matches this
// plugin instance are sent, so a shared host never notifies for another
// workspace's question. The JSON never travels through argv, a file, or a
// shell.


const QUESTION_NOTIFY_TITLE = "OpenCode question pending";
const QUESTION_NOTIFY_TIMEOUT_MS = 10000;
const QUESTION_NOTIFY_DELAY_MS = 300000;

// Keep the plugin's proactive bounds equivalent to the CLI normalization so a
// normal oversized form produces a bounded readable notification instead of a
// CLI rejection.
const QUESTION_INPUT_LIMIT_BYTES = 65536;
const MAX_QUESTIONS = 8;
const MAX_CHOICES = 12;
const TOTAL_TEXT_BUDGET = 8000;

const CAPS = {
  sessionId: 128,
  sessionTitle: 200,
  project: 240,
  header: 120,
  text: 1500,
  label: 160,
  description: 400,
};

const ARGV = ["phasegent", "notify", "send", "--stdin"];

function defaultSpawn(argv, options) {
  return Bun.spawn(argv, options);
}

function isQuestionForm(form) {
  if (!form || typeof form !== "object") return false;
  if (typeof form.id !== "string" || form.id.length === 0) return false;
  const metadata = form.metadata && typeof form.metadata === "object" ? form.metadata : null;
  return Boolean(metadata) && metadata.kind === "question";
}

function cleanText(raw) {
  if (typeof raw !== "string" || raw.length === 0) return "";
  return raw
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .replace(/[\u0000-\u0009\u000b-\u001f\u007f]/g, "")
    .trim();
}

// Charge `raw` against the shared budget and clip to `cap` scalars, appending a
// single ellipsis inside the cap when it does not fit. Never returns partial
// structure, only text.
function takeField(budget, raw, cap) {
  const cleaned = cleanText(raw);
  if (!cleaned) return "";
  const available = Math.min(cap, budget.remaining);
  if (available <= 0) return "";
  const chars = Array.from(cleaned);
  if (chars.length <= available) {
    budget.remaining -= chars.length;
    return cleaned;
  }
  const keep = Math.max(available - 1, 0);
  const clipped = `${chars.slice(0, keep).join("")}…`;
  budget.remaining -= Array.from(clipped).length;
  return clipped;
}

// Take the mandatory question text. Only real source content counts: a clip
// that would leave nothing but the ellipsis carries no question, so the text
// is not taken at all and the caller omits the question instead.
function takeQuestionText(budget, raw, cap) {
  const cleaned = cleanText(raw);
  if (!cleaned) return "";
  const available = Math.min(cap, budget.remaining);
  if (available < 2) return "";
  const chars = Array.from(cleaned);
  if (chars.length <= available) {
    budget.remaining -= chars.length;
    return cleaned;
  }
  const clipped = `${chars.slice(0, available - 1).join("")}…`;
  budget.remaining -= Array.from(clipped).length;
  return clipped;
}

function basename(value) {
  if (typeof value !== "string" || value.length === 0) return "";
  const trimmed = value.replace(/[\\/]+$/, "");
  const index = Math.max(trimmed.lastIndexOf("/"), trimmed.lastIndexOf("\\"));
  return index >= 0 ? trimmed.slice(index + 1) : trimmed;
}

// Project name is the basename of the host project directory, falling back to
// the plugin directory basename. The full absolute path is never disclosed.
function projectName(context) {
  const location = context && context.location;
  const projectDirectory =
    location && location.project && typeof location.project.directory === "string"
      ? location.project.directory
      : "";
  return basename(projectDirectory) || basename(locationDirectory(context));
}

async function readFormSession(context, sessionID) {
  const get = context && context.session && context.session.get;
  if (typeof get !== "function") return null;
  if (typeof sessionID !== "string" || sessionID.length === 0) return null;
  try {
    const result = await get({ sessionID });
    if (!result || typeof result !== "object") return null;
    const location = result.location && typeof result.location === "object" ? result.location : null;
    const directory = location && typeof location.directory === "string" ? location.directory : null;
    const workspaceID =
      location && typeof location.workspaceID === "string" ? location.workspaceID : null;
    const title = typeof result.title === "string" ? result.title : "";
    if (!directory && !title) return null;
    return { directory, workspaceID, title };
  } catch (_) {
    return null;
  }
}

// Build the bounded structured document the CLI parses. Field mapping: the form
// field title is the question header, the field description is the question
// text (falling back to the title), and a multiselect field maps to `multiple`.
// Empty optional strings stay empty.
//
// Every entry the plugin drops — beyond the question/choice caps, beyond the
// shared budget, missing real question text, or empty — is counted and reported
// as an omission so the recipient can see that content is missing instead of
// silently losing it. No question is ever rendered with invented text.
function buildQuestionPayload(context, form, session) {
  const budget = { remaining: TOTAL_TEXT_BUDGET };
  const sessionId = takeField(budget, form && form.sessionID, CAPS.sessionId) || "unknown";
  const sessionTitle = takeField(budget, session && session.title, CAPS.sessionTitle);
  const project = takeField(budget, projectName(context), CAPS.project);
  const fields = Array.isArray(form && form.fields) ? form.fields : [];
  const questions = [];
  let omittedQuestions = 0;
  for (const field of fields) {
    if (questions.length >= MAX_QUESTIONS) {
      omittedQuestions += 1;
      continue;
    }
    // The question text is mandatory, so it is allocated before the optional
    // header and choices: neither of them can starve it.
    let text = takeQuestionText(budget, field && field.description, CAPS.text);
    if (!text) text = takeQuestionText(budget, field && field.title, CAPS.text);
    if (!text) {
      // No real question text: the question is omitted and counted rather
      // than rendered with a stand-in.
      omittedQuestions += 1;
      continue;
    }
    const header = takeField(budget, field && field.title, CAPS.header);
    const rawOptions = Array.isArray(field && field.options) ? field.options : [];
    const options = [];
    let omittedOptions = 0;
    for (const option of rawOptions) {
      if (options.length >= MAX_CHOICES || budget.remaining <= 0) {
        omittedOptions += 1;
        continue;
      }
      const label = takeField(budget, option && option.label, CAPS.label);
      const description = takeField(budget, option && option.description, CAPS.description);
      if (!label && !description) {
        omittedOptions += 1;
        continue;
      }
      options.push({ label, description });
    }
    questions.push({
      header,
      text,
      multiple: Boolean(field && field.type === "multiselect"),
      options,
      omitted_options: omittedOptions,
    });
  }
  // `questions` may be empty: every field was dropped for lack of real text or
  // budget, which `omitted_questions` reports. The caller skips delivery for an
  // empty list instead of inventing a question to satisfy the CLI.
  return {
    event: "blocked",
    question: {
      session_id: sessionId,
      session_title: sessionTitle,
      project,
      questions,
      omitted_questions: omittedQuestions,
    },
  };
}

// `createQuestionNotifier` starts one abortable background subscriber and returns
// a disposer. `dependencies.spawn`/`dependencies.warn` are injectable so the
// delivery path is deterministic in tests; production uses `Bun.spawn` and the
// console warning channel. `dependencies.schedule`/`cancel`/`now` are the
// injectable timer seam, defaulting to `setTimeout`/`clearTimeout`/`Date.now`.
function createQuestionNotifier(context, dependencies = {}) {
  const spawn = typeof dependencies.spawn === "function" ? dependencies.spawn : defaultSpawn;
  const report = typeof dependencies.warn === "function" ? dependencies.warn : warn;
  const schedule =
    typeof dependencies.schedule === "function"
      ? dependencies.schedule
      : (callback, delay) => setTimeout(callback, delay);
  const cancel =
    typeof dependencies.cancel === "function"
      ? dependencies.cancel
      : (handle) => clearTimeout(handle);
  const now = typeof dependencies.now === "function" ? dependencies.now : Date.now;
  const subscribe = context && context.event && context.event.subscribe;
  if (typeof subscribe !== "function") {
    report("phasegent: host exposes no event subscription; question notifications are disabled");
    return () => {};
  }

  const controller = new AbortController();
  const pending = new Map();
  const settled = new Set();
  const deletedSessions = new Set();
  const children = new Set();
  let disposed = false;
  let streamEnded = false;

  const killChild = (child) => {
    if (child && typeof child.kill === "function") {
      try {
        child.kill();
      } catch (_) {}
    }
  };

  // Close the pipe and terminate the owned child. The exit is not awaited here:
  // a failed delivery may never produce one, and the child is released from the
  // owned set so disposal cannot clean it up twice.
  const terminateChild = (child) => {
    if (!child) return;
    children.delete(child);
    const exited = child.exited;
    if (exited && typeof exited.catch === "function") exited.catch(() => {});
    const sink = child.stdin;
    if (sink && typeof sink.end === "function") {
      try {
        sink.end();
      } catch (_) {}
    }
    killChild(child);
  };

  // Write the payload and close the pipe. A sink may report the write
  // asynchronously, so the write is awaited before the pipe is closed; a
  // pending write would otherwise be truncated by the close.
  const writeStdin = async (child, text) => {
    const sink = child && child.stdin;
    if (!sink || typeof sink.write !== "function") return;
    const written = sink.write(text);
    if (written && typeof written.then === "function") await written;
    if (typeof sink.end === "function") sink.end();
  };

  const clearTimer = (entry) => {
    if (entry && entry.timer !== null) {
      cancel(entry.timer);
      entry.timer = null;
    }
  };

  // A resolved identifier stays a compact lifetime tombstone even when its
  // create event was not tracked yet, so a late or replayed create can never
  // rearm an answered or delivered form. The tombstone holds no form payload and
  // is released with the notifier instance.
  const settleForm = (id) => {
    if (typeof id !== "string" || id.length === 0) return;
    settled.add(id);
    const entry = pending.get(id);
    if (!entry) return;
    entry.settled = true;
    clearTimer(entry);
    pending.delete(id);
  };

  // A deleted session is remembered independently of its current pending forms.
  // It rejects later creates for that session and releases matching timers and
  // payload entries at once.
  const settleSession = (sessionID) => {
    if (typeof sessionID !== "string" || sessionID.length === 0) return;
    deletedSessions.add(sessionID);
    for (const [id, entry] of pending) {
      if (entry.sessionID === sessionID) settleForm(id);
    }
  };

  const clearPending = () => {
    for (const entry of pending.values()) {
      entry.settled = true;
      clearTimer(entry);
    }
    pending.clear();
  };

  const isActive = (entry) =>
    !disposed &&
    !streamEnded &&
    !entry.settled &&
    pending.get(entry.id) === entry;

  const deliver = (entry) => {
    // Each delivery runs in an isolated task and is never awaited by the event
    // loop, so a slow or hung CLI (or session-title lookup) cannot stall event
    // handling or another question's deadline.
    const task = (async () => {
      if (!isActive(entry) || entry.delivering) return;
      entry.delivering = true;
      let child = null;
      try {
        // Reuse the session already fetched during location validation. A form
        // whose directory arrived with the event fetches only its title here.
        const enriched =
          entry.session || (await readFormSession(context, entry.form.sessionID));
        if (!isActive(entry)) return;
        const document = buildQuestionPayload(context, entry.form, enriched);
        if (document.question.questions.length === 0) {
          // Nothing but omissions: a question notification without a single
          // real question would have to invent one, so it is not sent.
          report("phasegent: question notification skipped: no question text");
          settleForm(entry.id);
          return;
        }
        // Resolution events are handled synchronously, so this is the last
        // eligibility check before the CLI is spawned.
        if (!isActive(entry)) return;
        const payload = JSON.stringify(document);
        const cwd = locationDirectory(context);
        child = spawn(ARGV, {
          cwd: cwd || undefined,
          env: process.env,
          stdin: "pipe",
          stdout: "ignore",
          stderr: "ignore",
          timeout: QUESTION_NOTIFY_TIMEOUT_MS,
        });
        if (child && typeof child === "object") children.add(child);
        settleForm(entry.id);
        if (disposed || streamEnded) {
          killChild(child);
          return;
        }
        try {
          await writeStdin(child, payload);
        } catch (_) {
          // A failed write is a delivery failure, not a question failure: the
          // pipe is closed and the owned child is terminated at once instead of
          // waiting for an exit that may never arrive.
          if (!disposed) report("phasegent: question notification delivery failed");
          terminateChild(child);
          return;
        }
        const exited = child && child.exited !== undefined ? child.exited : Promise.resolve(0);
        const code = await exited;
        if (typeof code === "number" && code !== 0 && !disposed) {
          report("phasegent: question notification delivery failed");
        }
      } catch (_) {
        if (!disposed) report("phasegent: question notification delivery failed");
        terminateChild(child);
      } finally {
        if (child) children.delete(child);
        if (pending.get(entry.id) === entry) settleForm(entry.id);
      }
    })();
    task.catch(() => {});
  };

  const onTimer = (entry) => {
    entry.timer = null;
    if (!isActive(entry)) return;
    const remaining = entry.deadline - now();
    if (remaining > 0) {
      entry.timer = schedule(() => onTimer(entry), remaining);
      return;
    }
    // A missing-location lookup may still be running. Waiting for this entry's
    // own lookup never delays another question, and the original deadline is
    // kept because no new deadline is recorded.
    const task = (async () => {
      if (entry.ready) await entry.ready;
      if (!isActive(entry) || entry.local !== true) return;
      deliver(entry);
    })();
    task.catch(() => {
      if (!disposed) report("phasegent: question notification handling failed");
    });
  };

  const track = (event, form) => {
    if (pending.has(form.id) || settled.has(form.id)) return null;
    const eventLocation =
      event.location && typeof event.location === "object" ? event.location : null;
    const hasEventDirectory = Boolean(
      eventLocation && typeof eventLocation.directory === "string",
    );
    const entry = {
      id: form.id,
      sessionID: typeof form.sessionID === "string" ? form.sessionID : "",
      form,
      event,
      session: null,
      local: hasEventDirectory ? true : null,
      settled: false,
      delivering: false,
      deadline: now() + QUESTION_NOTIFY_DELAY_MS,
      timer: null,
      ready: null,
    };
    pending.set(form.id, entry);
    entry.timer = schedule(() => onTimer(entry), QUESTION_NOTIFY_DELAY_MS);
    if (!hasEventDirectory) resolveLocation(entry);
    return entry;
  };

  // The form belongs to this plugin instance only when its directory equals the
  // plugin's own location; a missing/mismatched/unresolvable location skips (with
  // a safe warning when unknown), so a shared host never notifies cross-location.
  const formBelongsToInstance = (event, session) => {
    const own = locationDirectory(context);
    if (!own) {
      report("phasegent: question notification skipped: plugin location unavailable");
      return false;
    }
    const eventLocation =
      event.location && typeof event.location === "object" ? event.location : null;
    const directory =
      (eventLocation && typeof eventLocation.directory === "string"
        ? eventLocation.directory
        : null) ||
      (session && session.directory) ||
      null;
    if (!directory) {
      report("phasegent: question notification skipped: form location unknown");
      return false;
    }
    if (directory !== own) return false;
    const workspaceID =
      (eventLocation && typeof eventLocation.workspaceID === "string"
        ? eventLocation.workspaceID
        : null) || (session && session.workspaceID) || null;
    const ownWorkspace =
      context.location && typeof context.location.workspaceID === "string"
        ? context.location.workspaceID
        : null;
    if (workspaceID && ownWorkspace && workspaceID !== ownWorkspace) return false;
    return true;
  };

  // Resolve a missing event location in the entry's own task. The pending entry
  // is already armed, so a duplicate created event neither resets the deadline
  // nor starts a second lookup.
  const resolveLocation = (entry) => {
    entry.ready = (async () => {
      const session = await readFormSession(context, entry.form.sessionID);
      if (!isActive(entry)) return null;
      if (!formBelongsToInstance(entry.event, session)) {
        settleForm(entry.id);
        return null;
      }
      entry.session = session;
      entry.local = true;
      return session;
    })().catch(() => {
      if (isActive(entry)) {
        settleForm(entry.id);
        report("phasegent: question notification handling failed");
      }
      return null;
    });
  };

  const handleEvent = (event) => {
    if (disposed || streamEnded) return;
    if (!event || typeof event !== "object") return;
    if (event.type === "form.replied" || event.type === "form.cancelled") {
      const data = event.data && typeof event.data === "object" ? event.data : null;
      settleForm(data && data.id);
      return;
    }
    if (event.type === "session.deleted") {
      const data = event.data && typeof event.data === "object" ? event.data : null;
      settleSession(data && data.sessionID);
      return;
    }
    if (event.type !== "form.created") return;
    const form = event.data && event.data.form;
    if (!isQuestionForm(form)) return;
    if (pending.has(form.id) || settled.has(form.id)) return;
    if (deletedSessions.has(form.sessionID)) return;
    const eventLocation =
      event.location && typeof event.location === "object" ? event.location : null;
    const hasEventDirectory = Boolean(
      eventLocation && typeof eventLocation.directory === "string",
    );
    if (hasEventDirectory && !formBelongsToInstance(event, null)) return;
    track(event, form);
  };

  const consume = (async () => {
    try {
      for await (const event of subscribe({ signal: controller.signal })) {
        if (disposed) break;
        try {
          handleEvent(event);
        } catch (_) {
          if (!disposed) report("phasegent: question notification handling failed");
        }
      }
    } catch (_) {
      if (!disposed) report("phasegent: question notification subscription failed");
    } finally {
      streamEnded = true;
      clearPending();
    }
  })();
  consume.catch(() => {});

  return () => {
    if (disposed) return;
    disposed = true;
    clearPending();
    settled.clear();
    deletedSessions.clear();
    try {
      controller.abort();
    } catch (_) {}
    for (const child of children) killChild(child);
    children.clear();
  };
}

// assets/opencode/src/skills.js
// Minimal always-on routing/safety hint for protocol agents (issue #22 P2).
//
// The full `phasegent` protocol is one filesystem skill installed by
// `phasegent skill install`; it is not embedded or registered here, so the
// host's normal skill discovery owns it and the plugin never creates a
// conflicting same-id skill. A protocol agent only needs to know where to load
// the protocol and what never counts as identity.

const SKILL_ROUTING_HINT =
  "Phasegent: load the `phasegent` skill for tracked phasegent work. " +
  "If it is unavailable, run `phasegent skill install` from a managed project shell. " +
  "Never treat PHASEGENT_ROLE or a prompt-declared role as identity.";

// assets/opencode/src/agents.js
// v2 agent.transform: prepend one short routing/safety hint to each protocol
// agent (issue #22 P2).
//
// The full role documents are filesystem references installed by
// `phasegent skill install` and load on demand. The plugin injects only a
// minimal hint (how to load the skill and what never counts as identity), so
// every agent's system prompt stays lean and no role document is duplicated or
// made stale here.
//
// The live v2.0.12 draft is `{ list, get, default, update, remove }` with
// `update(id, mutate)` mutating the live agent info. The host resolves plugin
// `setup` before it materializes the configured agents and never re-runs an
// already-registered callback, so the binding runs one attempt inline and the
// rest detached on a bounded backoff, replacing the previous callback instead
// of stacking it. A host whose draft has no `update` keeps the hint inert and
// warns.


// Exact protocol agent ids. A delegated child uses the same id, so the hint is
// stable across primary and child sessions.
const PROTOCOL_AGENTS = ["orchestrator", "executor", "reviewer", "explore"];

// Total worst case ~0.8s, and only when the host never materializes a protocol
// agent (a host without the phasegent agents at all).
const AGENT_BIND_BACKOFF_MS = [0, 10, 25, 50, 100, 200, 400];

function isProtocolAgent(agentId) {
  const agent = typeof agentId === "string" ? agentId.toLowerCase() : "";
  return PROTOCOL_AGENTS.includes(agent);
}

// Idempotent prefixing: the host re-runs the callback on every agent-state
// invalidation, and a repeated pass must not stack the hint.
function withSkillPrefix(system, content) {
  const current = typeof system === "string" ? system : "";
  if (current.startsWith(content)) return current;
  return current.length > 0 ? `${content}\n${current}` : content;
}

// One registration pass: prepend the hint to each present protocol agent and
// report how many protocol agents were seen and how many are bound now.
function bindPresentAgents(draft) {
  const protocol = [];
  for (const info of draft.list()) {
    const id = info && typeof info.id === "string" ? info.id : "";
    if (isProtocolAgent(id)) protocol.push(id);
  }
  let bound = 0;
  for (const id of protocol) {
    draft.update(id, (entry) => {
      if (!entry || typeof entry !== "object") return;
      entry.system = withSkillPrefix(entry.system, SKILL_ROUTING_HINT);
    });
    bound += 1;
  }
  return { protocol, bound };
}

async function registerAgentSkills(context, deps) {
  const agent = context && context.agent;
  const transform = agent && agent.transform;
  if (typeof transform !== "function") {
    warn("phasegent: host exposes no agent.transform; the routing hint stays uninjected");
    return null;
  }
  const backoff = (deps && deps.backoff) || AGENT_BIND_BACKOFF_MS;
  const wait = (deps && deps.wait) || ((ms) => new Promise((resolve) => setTimeout(resolve, ms)));
  const holder = { registration: null, disposed: false, settled: false, bound: 0, seen: new Set() };

  const runAttempt = async () => {
    if (holder.disposed) return;
    const previous = holder.registration;
    holder.registration = await transform((draft) => {
      if (!draft || typeof draft.list !== "function" || typeof draft.update !== "function") {
        warn("phasegent: host agent draft exposes no update; the routing hint stays uninjected");
        return;
      }
      try {
        const pass = bindPresentAgents(draft);
        for (const id of pass.protocol) holder.seen.add(id);
        holder.bound = pass.bound;
      } catch (error) {
        warn(`phasegent: routing hint injection was rejected (${errorText(error)})`);
      }
    });
    // Replace the stale callback: it would otherwise keep re-running on every
    // agent-state invalidation for the lifetime of the plugin.
    if (previous && typeof previous.dispose === "function") {
      try {
        await previous.dispose();
      } catch (_) {
        // A failed dispose only leaves an extra inert callback registered.
      }
    }
    if (holder.bound > 0 && holder.bound >= holder.seen.size) holder.settled = true;
  };

  await runAttempt();
  // The host resolves `setup` first and materializes the configured agents
  // afterwards; a callback registered while setup is still awaiting therefore
  // only ever sees the built-in agents, and the host never re-runs it for a
  // later load. The remaining attempts run detached on a bounded backoff so
  // setup stays non-blocking, and they stop as soon as every protocol agent
  // that appeared is bound.
  const settle = (async () => {
    for (let index = 1; index < backoff.length && !holder.settled; index += 1) {
      await wait(backoff[index]);
      if (holder.disposed) return;
      await runAttempt();
    }
    if (!holder.settled && holder.bound === 0) {
      warn("phasegent: no protocol agent was found; the routing hint stays uninjected");
    }
  })().catch((error) => {
    warn(`phasegent: routing hint binding failed (${errorText(error)})`);
  });

  return {
    settle,
    async dispose() {
      holder.disposed = true;
      const registration = holder.registration;
      if (registration && typeof registration.dispose === "function") {
        await registration.dispose();
      }
    },
  };
}

// assets/opencode/src/strategy.js
// v2 worktree strategy. `editor.add` selects the strategy as the default, and
// the v2 editor has no way to wrap the host git strategy, so the strategy is
// only claimed when the checkout is already phasegent-bound; otherwise the host
// keeps its own git implementation. A host "create worktree" action is the
// explicit isolation opt-in (issue 616), so `create` passes `isolate` and a
// dedicated directory is really created instead of quietly reusing the current
// checkout. Host removal is refused: the directory, its branch and its lease
// belong to the phasegent cleanup lifecycle.


// Mirrors the host git strategy's command (packages/core/src/git.ts:657) so a
// failed lease never breaks worktree creation in a phasegent checkout.
async function gitWorktreeAdd(input) {
  const directory = input && input.directory;
  const sourceDirectory = input && input.sourceDirectory;
  if (typeof directory !== "string" || directory.length === 0) {
    throw new Error("phasegent: worktree create requires a destination directory");
  }
  const ref = input && typeof input.branch === "string" && input.branch.length > 0
    ? input.branch
    : "HEAD";
  const command = Bun.$`git worktree add --detach -- ${directory} ${ref}`;
  const result = await safeText((sourceDirectory ? command.cwd(sourceDirectory) : command).quiet());
  if (!result.ok) {
    throw new Error(`phasegent: git worktree add failed: ${result.error}`);
  }
  return { directory };
}

function worktreeStrategyDefinition(options) {
  const issueId = options.issueId;
  const fallbackDirectory = options.directory;
  return {
    id: "phasegent",
    async create(input) {
      const sourceDirectory = input && typeof input.sourceDirectory === "string"
        ? input.sourceDirectory
        : fallbackDirectory;
      // A host "create worktree" action is the explicit opt-in (issue 616):
      // without `--isolate` the acquire may reuse the current checkout, which
      // would not honour the create request. The host action carries no
      // session, and anonymous acquisition is refused since issue 651 P4, so
      // this always degrades to the plain git worktree below — no lease is
      // ever booked without an owner.
      const acquired = await options.acquire(issueId, null, sourceDirectory, { isolate: true });
      if (acquired && typeof acquired.path === "string" && acquired.path.length > 0) {
        return { directory: acquired.path };
      }
      warn("phasegent: worktree acquire failed; falling back to a plain git worktree");
      return await options.gitAdd(input);
    },
    async remove() {
      // The host drops the worktree from its inventory once this resolves, so
      // a silent success would hide a worktree that still exists. The
      // directory, its branch and its lease belong to the phasegent cleanup
      // lifecycle, so refuse.
      throw new Error(
        "phasegent: host removal is unsupported for phasegent worktrees; remove them through the phasegent-managed issue cleanup lifecycle (`phasegent issue close`, `phasegent issue sync`)",
      );
    },
    async list(sourceDirectory) {
      const root = typeof sourceDirectory === "string" && sourceDirectory.length > 0
        ? sourceDirectory
        : fallbackDirectory;
      const entries = [];
      const seen = new Set();
      const push = (directory, type) => {
        if (typeof directory !== "string" || directory.length === 0) return;
        if (seen.has(directory)) return;
        seen.add(directory);
        entries.push({ directory, type });
      };
      push(root, "root");
      const leases = await options.readLeases(issueId, root);
      for (const lease of leases || []) {
        if (!lease || typeof lease !== "object") continue;
        push(lease.worktree_path, "worktree");
      }
      return entries;
    },
  };
}

// `deps` is an internal seam so tests can exercise the strategy without the
// phasegent CLI; production callers pass nothing. `PHASEGENT_WORKTREE_NO_DISCOVER=1`
// keeps the adapter from running the CLI at all, and then the host keeps its own
// git strategy. The binding is probed once per plugin instance: a checkout that
// gains its binding later keeps the host git strategy until the plugin reloads.
async function registerWorktreeStrategy(context, deps) {
  if (phasegentCallsDisabled()) return null;
  const worktree = context && context.worktree;
  const transform = worktree && worktree.transform;
  if (typeof transform !== "function") {
    warn("phasegent: host exposes no worktree.transform; the git strategy stays in place");
    return null;
  }
  const directory = locationDirectory(context);
  const readBinding = (deps && deps.readBinding) || readBranchBinding;
  const issueId = await readBinding(directory);
  if (!issueId) return null;
  const definition = worktreeStrategyDefinition({
    issueId,
    directory,
    acquire: (deps && deps.acquire) || acquireWorktree,
    gitAdd: (deps && deps.gitAdd) || gitWorktreeAdd,
    readLeases: (deps && deps.readLeases) || readIssueLeases,
  });
  return await transform((editor) => {
    editor.add(definition);
  });
}

// assets/opencode/src/index.js
// OpenCode v2 worktree adapter — source entry.
//
// The deployable artifact is the checked-in single file
// `assets/opencode/phasegent-worktree.js`, generated from this tree by
// `bun run build:plugin` (see `build.js`). The protocol prompt is the
// filesystem skill installed by `phasegent skill install`; the adapter carries
// only a short routing/safety hint.
//
// OpenCode >= 2.0 is required: the v1 plugin shape is rejected by the v2 module
// loader (`PluginModule.LoadError: Plugin must export a default definition with
// an id and an effect or setup function.`,
// packages/core/src/plugin/module.ts:60-73, :111). The v2 contract is
// `export default { id, setup }`; `setup(context)` registers hooks imperatively
// and returns a cleanup (packages/plugin/src/promise/plugin.ts:56-61).
//
//   * `context.session.hook("prompt", event)` — the same mutable payload object
//     for every submitted turn (`{ sessionID, messageID, prompt, metadata,
//     delivery }`, core `SessionPrompt.prepare`). It owns worktree placement
//     (issue 37): a session is registered, inherited, or discovered and then
//     moved before the runner reaches any tool call, so a Task-spawned child
//     follows its parent's directory and no tool invocation is ever cancelled to
//     move a session.
//   * `context.tool.hook("execute.before", event)` — one mutable event
//     `{ tool, sessionID, agent, messageID, id, input }`; core continues with the
//     returned `event.input` (packages/core/src/tool.ts:103-111, :271-280). It
//     only rewrites shell commands, so role/session injection stays available
//     and path rewriting stays absent.
//   * `context.worktree.transform(editor => editor.add({ id, create, remove, list }))`
//     (packages/plugin/src/promise/worktree.ts:5-22). It has no v1 `target`
//     callback, so the acquired worktree becomes the session directory through
//     `context.session.move` (packages/core/src/session/move.ts:41-49). The strategy
//     is only claimed when the checkout already carries a phasegent issue binding,
//     so a non-phasegent project keeps the host git strategy.
//   * `context.agent.transform(draft => draft.update(id, mutate))` prepends one
//     short routing/safety hint to each protocol agent's `system`. The full
//     protocol and role references are one filesystem skill installed by
//     `phasegent skill install`; the plugin registers no embedded duplicate and
//     injects no full role document. The live v2.0.12 draft is
//     `{ list, get, default, update, remove }`, and `update` mutates the live
//     agent info (its `system` included). The callback is re-run whenever the
//     agent state invalidates, so the prefix is applied idempotently.
//   * No slash command: the live v2.0.11 command draft exposes only
//     `add({ name, description, execute })`, and `execute` must return an
//     Effect that a promise plugin cannot build. Registering through the
//     typed SDK's `update(name, mutate)` draft raised a `TypeError` and the
//     host then disabled the whole plugin, redirect hook included (issue #533
//     host evidence), so `phasegent worktree acquire` stays the manual path.
//
// The npm `@opencode-ai/plugin` type package can lag the binary it ships with
// (`tool`, `worktree`, `session` and `location` are absent from 1.18.25 while
// the binary exposes them); the adapter targets the binary's runtime context.
//
// Session identity is `event.sessionID`, and a Task-spawned child reads its
// `parentID` through `context.session.get` in the prompt hook so it inherits the
// parent's directory instead of guessing from the most recently remembered
// worktree (session.js). Degradation is deliberate: no binding or a failed
// acquire keeps the original directory and warns on the console (v2 has no
// structured warning channel). A lease row that `issue close` / `issue sync`
// converged keeps its "issue closed…" release reason, so the lazy path refuses to
// acquire a fresh worktree for an already closed issue and stays in place (issue
// #575 P2). The host is also the authority that outranks the registry: `issue
// close` returns the closing session to the main checkout through the OpenCode
// API before removing its worktree, and a settled placement is reconciled against
// a fresh host read so that relocation is never reversed and a removed worktree is
// never re-entered by this session or a later child (issue #747 P2,
// session-reconcile.js). Absolute paths pass through untouched, so an explicit
// escape and the external_directory check that guards it are never rewritten. All
// worktree calls stay local: no network, no credentials, no .env copies. Branches
// and directories are never deleted here; removal is `phasegent worktree prune`.

const PhasegentWorktreePlugin = {
  id: "phasegent-worktree",
  async setup(context) {
    const registrations = [];
    // Per-plugin-instance managed shell bridge (issue #859 P1): one Map per
    // setup, never a global. It is only wired into the tool hook when the
    // host exposes the shell hook; otherwise the rewrite-only path stays.
    //
    // The loopback identity broker (issue #22 P1) is the only source of an
    // agent role: the CLI asks it, the broker answers from the host facts it
    // stored for the live tool call. Without a broker the managed shell
    // still carries the session marker, so the CLI fails closed instead of
    // becoming an ordinary operator CLI.
    let shellBridge = null;
    let shellBridgeEnabled = false;
    let identityBroker = null;
    try {
      if (isShellHookSupported(context)) {
        identityBroker = createIdentityBroker();
        await identityBroker.start();
        shellBridge = createManagedShellBridge({ broker: identityBroker });
        shellBridgeEnabled = true;
      } else {
        warn("phasegent: host exposes no shell hook; managed shell env is disabled, command rewriting stays available");
      }
    } catch (error) {
      warn(`phasegent: managed shell bridge unavailable (${errorText(error)})`);
      if (identityBroker && typeof identityBroker.stop === "function") {
        try {
          identityBroker.stop();
        } catch (_) {
          // stopping a broker must never break the host
        }
      }
      identityBroker = null;
      shellBridge = null;
      shellBridgeEnabled = false;
    }
    try {
      const strategy = await registerWorktreeStrategy(context);
      if (strategy) registrations.push(strategy);
    } catch (error) {
      warn(`phasegent: worktree strategy registration failed (${errorText(error)})`);
    }
    try {
      // The prompt hook owns placement: it is admitted before the runner reaches
      // any tool call, so no tool invocation is cancelled to move a session.
      const promptHook = context && context.session && context.session.hook;
      if (typeof promptHook === "function") {
        registrations.push(await promptHook("prompt", createPromptHook(context)));
      } else {
        warn("phasegent: host exposes no session prompt hook; worktree placement is disabled");
      }
    } catch (error) {
      warn(`phasegent: session.prompt registration failed (${errorText(error)})`);
    }
    try {
      // The tool hook rewrites phasegent commands and, when the shell bridge
      // is enabled, decorates the rewritten command with the inert nonce
      // header for the shell hook to consume. It carries no placement state.
      const hook = context && context.tool && context.tool.hook;
      if (typeof hook === "function") {
        registrations.push(
          await hook(
            "execute.before",
            createRedirectHook(shellBridgeEnabled ? shellBridge : null),
          ),
        );
        // Best-effort after-hook cleanup for cancelled/failed calls; TTL and
        // capacity still bound the map when the host exposes no after hook.
        if (shellBridgeEnabled && shellBridge) {
          try {
            registrations.push(
              await hook("execute.after", createToolAfterHook(shellBridge)),
            );
          } catch (error) {
            warn(`phasegent: tool.execute.after registration failed (${errorText(error)})`);
          }
        }
      } else {
        warn("phasegent: host exposes no tool hook; command rewriting is disabled");
      }
    } catch (error) {
      warn(`phasegent: tool.execute.before registration failed (${errorText(error)})`);
    }
    try {
      // The shell hook consumes the nonce header once, restores the exact
      // rewritten bytes, and sets only the fresh env properties. It never
      // guesses an identity for forged, mismatched, expired, or replayed
      // headers; the host native marker then fails closed.
      if (shellBridgeEnabled && shellBridge) {
        const shellHook = context && context.shell && context.shell.hook;
        if (typeof shellHook === "function") {
          try {
            registrations.push(
              await shellHook("create.before", createShellEnvHook(shellBridge)),
            );
          } catch (error) {
            warn(`phasegent: shell.create.before registration failed (${errorText(error)})`);
          }
        } else {
          warn("phasegent: shell hook unavailable; managed shell env stays disabled");
        }
      }
    } catch (error) {
      warn(`phasegent: shell hook registration failed (${errorText(error)})`);
    }
    try {
      const bound = await registerAgentSkills(context);
      if (bound) registrations.push(bound);
    } catch (error) {
      warn(`phasegent: agent.transform registration failed (${errorText(error)})`);
    }
    try {
      // Best-effort question notifications (issue #1026 P1): one bounded
      // `phasegent notify send` per new local pending question form. The
      // subscription degrades to a warning when the host exposes none, and the
      // notifier's disposer joins the plugin's cleanup.
      registrations.push({ dispose: createQuestionNotifier(context) });
    } catch (error) {
      warn(`phasegent: question notifier registration failed (${errorText(error)})`);
    }
    return async () => {
      for (const registration of registrations) {
        try {
          if (registration && typeof registration.dispose === "function") {
            await registration.dispose();
          }
        } catch (_) {
        }
      }
      if (identityBroker && typeof identityBroker.stop === "function") {
        try {
          identityBroker.stop();
        } catch (_) {
        }
      }
    };
  },
};

PhasegentWorktreePlugin.redirect = Object.freeze({
  isAbsolutePath,
  redirectPathValue,
  redirectPaths,
  agentName,
  agentRole,
  isSubagentSession,
  sessionPlaced,
  rewritePhasegentCommand,
  scanHeredocRanges,
  maskQuoted,
  shellSegments,
  transformCodeOnly,
  phasegentInvocation,
  rememberWorktree,
  worktreeForSession,
  resetWorktrees,
  createRedirectHook,
  createPromptHook,
  createManagedShellBridge,
  createShellEnvHook,
  createToolAfterHook,
  createIdentityBroker,
  BROKER_ADDR_ENV,
  BROKER_TOKEN_ENV,
  isShellHookSupported,
  pickActiveWorktreePath,
  issueClosedLocally,
  discoverWorktreeForSession,
  ensureSessionWorktree,
  moveSessionToWorktree,
  readSessionInfo,
  readAuthoritativeDirectory,
  inheritedWorktree,
  reconcileSessionLocation,
  readBranchBinding,
  acquireWorktree,
  readIssueLeases,
  readIssueLeaseHistory,
  registerWorktreeStrategy,
  worktreeStrategyDefinition,
  gitWorktreeAdd,
  registerAgentSkills,
  isProtocolAgent,
  withSkillPrefix,
  SKILL_ROUTING_HINT,
  createQuestionNotifier,
});

export default PhasegentWorktreePlugin;
